mkdir -p src/lib src/components src/styles content/cases scripts supabase/migrations tests e2e && cat > src/lib/env.ts <<'EOF'
import { z } from "zod";

/**
 * Переменные окружения проверяются один раз при первом обращении.
 * Если чего-то не хватает, приложение падает сразу с понятным списком,
 * а не молча ломается посреди запроса.
 */

const serverSchema = z.object({
  NEXT_PUBLIC_SITE_URL: z.url(),
  NEXT_PUBLIC_SUPABASE_URL: z.url(),
  SUPABASE_SECRET_KEY: z.string().min(20),
  TELEGRAM_BOT_TOKEN: z.string().regex(/^\d+:[\w-]+$/, "не похоже на токен бота"),
  TELEGRAM_CHAT_ID: z.string().regex(/^-?\d+$/, "должен быть числом"),
  TELEGRAM_ADMIN_USER_ID: z.string().regex(/^\d+$/, "должен быть числом"),
  TELEGRAM_WEBHOOK_SECRET: z.string().min(16),
  IP_HASH_SALT: z.string().min(16),
});

export type ServerEnv = z.infer<typeof serverSchema>;

let cached: ServerEnv | null = null;

export function serverEnv(): ServerEnv {
  if (cached) return cached;

  const parsed = serverSchema.safeParse({
    NEXT_PUBLIC_SITE_URL: process.env.NEXT_PUBLIC_SITE_URL,
    NEXT_PUBLIC_SUPABASE_URL: process.env.NEXT_PUBLIC_SUPABASE_URL,
    SUPABASE_SECRET_KEY: process.env.SUPABASE_SECRET_KEY,
    TELEGRAM_BOT_TOKEN: process.env.TELEGRAM_BOT_TOKEN,
    TELEGRAM_CHAT_ID: process.env.TELEGRAM_CHAT_ID,
    TELEGRAM_ADMIN_USER_ID: process.env.TELEGRAM_ADMIN_USER_ID,
    TELEGRAM_WEBHOOK_SECRET: process.env.TELEGRAM_WEBHOOK_SECRET,
    IP_HASH_SALT: process.env.IP_HASH_SALT,
  });

  if (!parsed.success) {
    const problems = parsed.error.issues
      .map((issue) => `  ${issue.path.join(".")}: ${issue.message}`)
      .join("\n");
    throw new Error(
      `Не настроены переменные окружения (см. .env.example):\n${problems}`,
    );
  }

  cached = parsed.data;
  return cached;
}

/** Адрес сайта доступен и без остальных настроек — нужен для ссылок в разметке. */
export function siteUrl(): string {
  return process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000";
}
EOF
npx tsc --noEmit -p tsconfig.json 2>&1 | head -20 && echo "типы ок"

