import "server-only";

import fs from "node:fs/promises";
import path from "node:path";

import matter from "gray-matter";
import { z } from "zod";

const CONTENT_DIR = path.join(process.cwd(), "content", "cases");

/** Путь к файлу внутри public/, например /cases/avito-smb/cover.png */
const publicPath = z
  .string()
  .startsWith("/", "путь должен начинаться со слэша и лежать в public/");

const attachmentSchema = z.object({
  title: z.string().min(1),
  href: z.string().min(1),
});

const frontmatterSchema = z.object({
  title: z.string().min(3),
  company: z.string().min(1).optional(),
  /** Месяц в формате ГГГГ-ММ — по нему сортируется список. */
  period: z.string().regex(/^\d{4}-\d{2}$/, "ожидается формат ГГГГ-ММ"),
  role: z.string().min(1).optional(),
  summary: z.string().min(10),
  tags: z.array(z.string().min(1)).default([]),
  cover: publicPath.optional(),
  visibility: z.enum(["public", "unlisted"]).default("public"),
  outcome: z.string().min(1).optional(),
  attachments: z.array(attachmentSchema).default([]),
});

export type CaseFrontmatter = z.infer<typeof frontmatterSchema>;

export type CaseMeta = CaseFrontmatter & { slug: string };

export type CaseEntry = CaseMeta & { body: string };

/** Имена папок в content/cases. Папки, начинающиеся с точки или _, пропускаются. */
async function readSlugs(): Promise<readonly string[]> {
  let entries;
  try {
    entries = await fs.readdir(CONTENT_DIR, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }

  return entries
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((name) => !name.startsWith(".") && !name.startsWith("_"))
    .sort();
}

/**
 * Читает один кейс. Возвращает null, если папки нет.
 * Кривой frontmatter — это ошибка сборки, а не пустая страница.
 */
export async function getCaseBySlug(slug: string): Promise<CaseEntry | null> {
  if (!/^[a-z0-9-]+$/.test(slug)) return null;

  const file = path.join(CONTENT_DIR, slug, "index.mdx");

  let raw: string;
  try {
    raw = await fs.readFile(file, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }

  const { data, content } = matter(raw);
  const parsed = frontmatterSchema.safeParse(data);

  if (!parsed.success) {
    const problems = parsed.error.issues
      .map((issue) => `  ${issue.path.join(".") || "(корень)"}: ${issue.message}`)
      .join("\n");
    throw new Error(`Кейс content/cases/${slug}/index.mdx заполнен неверно:\n${problems}`);
  }

  return { ...parsed.data, slug, body: content };
}

async function getAllEntries(): Promise<readonly CaseEntry[]> {
  const slugs = await readSlugs();
  const entries = await Promise.all(slugs.map((slug) => getCaseBySlug(slug)));
  return entries.filter((entry): entry is CaseEntry => entry !== null);
}

/** Все слаги, включая скрытые — нужны, чтобы страницы собрались заранее. */
export async function getAllSlugs(): Promise<readonly string[]> {
  const entries = await getAllEntries();
  return entries.map((entry) => entry.slug);
}

/** Кейсы для списка: только публичные, свежие сверху. */
export async function getPublicCases(): Promise<readonly CaseMeta[]> {
  const entries = await getAllEntries();
  return entries
    .filter((entry) => entry.visibility === "public")
    .map(({ body: _body, ...meta }) => meta)
    .sort((a, b) => b.period.localeCompare(a.period));
}
