import { z } from "zod";

export const MAX_FILE_BYTES = 20 * 1024 * 1024;

/** Разрешённые типы документов: расширение → допустимые MIME-типы. */
const ALLOWED_FILES: Readonly<Record<string, readonly string[]>> = {
  ".pdf": ["application/pdf"],
  ".docx": [
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  ],
  ".doc": ["application/msword"],
};

export const ALLOWED_EXTENSIONS = Object.keys(ALLOWED_FILES);

/** Браузеры не всегда угадывают тип файла — такой ответ считаем «тип не указан». */
const UNKNOWN_MIME = new Set(["", "application/octet-stream", "binary/octet-stream"]);

/** Минимальное время заполнения формы. Быстрее — почти наверняка бот. */
export const MIN_FILL_MS = 3000;

/** Ссылки принимаем только по http(s) — никаких javascript: и data:. */
const externalUrlSchema = z
  .url("нужна полная ссылка, начиная с https://")
  .refine(
    (value) => {
      try {
        return ["http:", "https:"].includes(new URL(value).protocol);
      } catch {
        return false;
      }
    },
    { message: "поддерживаются только ссылки http и https" },
  );

export const submissionFieldsSchema = z.object({
  authorName: z.string().trim().min(2, "укажите имя").max(80),
  authorEmail: z.email("проверьте адрес почты").max(160),
  authorContact: z.string().trim().max(120).optional().or(z.literal("")),
  title: z.string().trim().min(3, "укажите название кейса").max(140),
  company: z.string().trim().max(120).optional().or(z.literal("")),
  summary: z
    .string()
    .trim()
    .min(30, "опишите кейс хотя бы парой предложений")
    .max(1000, "слишком длинно — уложитесь в 1000 знаков"),
  externalUrl: externalUrlSchema.optional().or(z.literal("")),
  consent: z.literal(true, { message: "нужно согласие на публикацию" }),
});

export type SubmissionFields = z.infer<typeof submissionFieldsSchema>;

export type FileCheck =
  | { ok: true; extension: string }
  | { ok: false; message: string };

/** Проверяет присланный файл по размеру, расширению и типу. */
export function checkFile(name: string, size: number, mime: string): FileCheck {
  const extension = name.slice(name.lastIndexOf(".")).toLowerCase();
  const allowedMimes = ALLOWED_FILES[extension];

  if (!allowedMimes) {
    return {
      ok: false,
      message: `можно приложить только ${ALLOWED_EXTENSIONS.join(", ")}`,
    };
  }

  if (size <= 0) {
    return { ok: false, message: "файл пустой" };
  }

  if (size > MAX_FILE_BYTES) {
    return { ok: false, message: "файл больше 20 МБ" };
  }

  const normalizedMime = mime.split(";")[0]!.trim().toLowerCase();
  if (!allowedMimes.includes(normalizedMime) && !UNKNOWN_MIME.has(normalizedMime)) {
    return { ok: false, message: "содержимое файла не совпадает с расширением" };
  }

  return { ok: true, extension };
}

/** Ловушка для ботов: скрытое поле должно остаться пустым, форма — заполняться не мгновенно. */
export function looksLikeBot(honeypot: string, elapsedMs: number): boolean {
  return honeypot.trim().length > 0 || elapsedMs < MIN_FILL_MS;
}
