export function clientIp(headers: Headers): string {
  const forwarded = headers.get("x-forwarded-for");
  if (forwarded) {
    const first = forwarded.split(",")[0]?.trim();
    if (first) return first;
  }
  return headers.get("x-real-ip")?.trim() || "unknown";
}

export type RateLimitResult = { allowed: boolean; used: number };

/**
 * Считает попытки за последний час и регистрирует текущую.
 * Если база недоступна — пропускаем запрос дальше: форма важнее лимита.
 */
export async function checkRateLimit(ipHash: string): Promise<RateLimitResult> {
  const supabase = supabaseAdmin();
  const since = new Date(Date.now() - WINDOW_MS).toISOString();

  const { count, error } = await supabase
    .from("submission_attempts")
    .select("id", { count: "exact", head: true })
    .eq("ip_hash", ipHash)
    .gte("created_at", since);

  if (error) {
    console.error("[rate-limit] не удалось посчитать попытки:", error.message);
    return { allowed: true, used: 0 };
  }

  const used = count ?? 0;
  if (used >= HOURLY_LIMIT) return { allowed: false, used };

  const { error: insertError } = await supabase
    .from("submission_attempts")
    .insert({ ip_hash: ipHash });

  if (insertError) {
    console.error("[rate-limit] не удалось записать попытку:", insertError.message);
  }

  return { allowed: true, used: used + 1 };
}
