import type { SubmissionStatus } from "./types";

/** Экранирование для parse_mode: HTML. */
export function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
}

export type InlineKeyboard = {
  inline_keyboard: { text: string; callback_data: string }[][];
};

export type CardInput = {
  id: string;
  title: string;
  authorName: string;
  authorEmail: string;
  authorContact?: string | null;
  company?: string | null;
  summary: string;
  externalUrl?: string | null;
  fileName?: string | null;
};

function line(label: string, value: string | null | undefined): string | null {
  if (!value) return null;
  return `${label}: ${escapeHtml(value)}`;
}

/** Текст карточки заявки. Чистая функция — её проверяют тесты. */
export function buildCardText(input: CardInput): string {
  const rows = [
    `<b>${escapeHtml(input.title)}</b>`,
    "",
    line("Автор", input.authorName),
    line("Почта", input.authorEmail),
    line("Контакт", input.authorContact),
    line("Компания", input.company),
    "",
    escapeHtml(input.summary),
    "",
    input.externalUrl ? `Ссылка: ${escapeHtml(input.externalUrl)}` : null,
    input.fileName ? `Файл: ${escapeHtml(input.fileName)} (отправлю следующим сообщением)` : null,
  ];

  return rows.filter((row) => row !== null).join("\n").replace(/\n{3,}/g, "\n\n");
}

/** Кнопки модерации. callback_data должна уместиться в 64 байта. */
export function buildKeyboard(id: string): InlineKeyboard {
  return {
    inline_keyboard: [
      [
        { text: "✅ Одобрить", callback_data: `approve:${id}` },
        { text: "❌ Отклонить", callback_data: `reject:${id}` },
      ],
    ],
  };
}

export type CallbackAction = { action: "approve" | "reject"; id: string };

/** Разбирает callback_data. Возвращает null на всём, что не наш формат. */
export function parseCallbackData(data: string): CallbackAction | null {
  const match = /^(approve|reject):([0-9a-f-]{36})$/.exec(data);
  if (!match) return null;
  return { action: match[1] as "approve" | "reject", id: match[2]! };
}

/** Текст, на который заменяется карточка после решения. */
export function buildDecisionText(
  original: string,
  status: Exclude<SubmissionStatus, "pending">,
  publicUrl: string | null,
): string {
  if (status === "approved") {
    const link = publicUrl ? `\n${escapeHtml(publicUrl)}` : "";
    return `${original}\n\n<b>✅ Опубликовано</b>${link}`;
  }
  return `${original}\n\n<b>❌ Отклонено</b>`;
}
EOF
