import "server-only";

import { serverEnv } from "./env";
import {
  buildCardText,
  buildKeyboard,
  type CardInput,
  type InlineKeyboard,
} from "./telegram-message";

type TelegramResponse<T> =
  | { ok: true; result: T }
  | { ok: false; description?: string; error_code?: number };

async function callTelegram<T>(
  method: string,
  payload: Record<string, unknown> | FormData,
): Promise<T> {
  const { TELEGRAM_BOT_TOKEN } = serverEnv();
  const url = `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/${method}`;

  const response =
    payload instanceof FormData
      ? await fetch(url, { method: "POST", body: payload })
      : await fetch(url, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body: JSON.stringify(payload),
        });

  const json = (await response.json()) as TelegramResponse<T>;

  if (!json.ok) {
    throw new Error(`Telegram ${method}: ${json.description ?? response.status}`);
  }

  return json.result;
}

/** Отправляет карточку заявки с кнопками. Возвращает id сообщения. */
export async function sendSubmissionCard(input: CardInput): Promise<number> {
  const { TELEGRAM_CHAT_ID } = serverEnv();

  const message = await callTelegram<{ message_id: number }>("sendMessage", {
    chat_id: TELEGRAM_CHAT_ID,
    text: buildCardText(input),
    parse_mode: "HTML",
    link_preview_options: { is_disabled: true },
    reply_markup: buildKeyboard(input.id),
  });

  return message.message_id;
}

