  mime: string,
  replyToMessageId: number,
): Promise<void> {
  const { TELEGRAM_CHAT_ID } = serverEnv();

  const form = new FormData();
  form.set("chat_id", TELEGRAM_CHAT_ID);
  form.set("reply_to_message_id", String(replyToMessageId));
  form.set("disable_notification", "true");
  form.set("document", new Blob([bytes], { type: mime }), fileName);

  await callTelegram<unknown>("sendDocument", form);
}

