import "server-only";

import { SUBMISSIONS_BUCKET, supabaseAdmin } from "./supabase";
import type { SubmissionRow, SubmissionStatus } from "./types";

/** Ссылка на файл живёт час — этого хватает, чтобы открыть или скачать документ. */
const SIGNED_URL_TTL_SECONDS = 60 * 60;

/** Оставляем в имени файла только безопасные символы, расширение сохраняем. */
export function safeFileName(name: string): string {
  const dot = name.lastIndexOf(".");
  const base = (dot > 0 ? name.slice(0, dot) : name)
    .normalize("NFKD")
    .replace(/[^\w.-]+/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
  const extension = dot > 0 ? name.slice(dot).toLowerCase() : "";
  return `${base || "document"}${extension}`;
}

export type NewSubmission = {
  id: string;
  authorName: string;
  authorEmail: string;
  authorContact: string | null;
  title: string;
  company: string | null;
  summary: string;
  externalUrl: string | null;
  filePath: string | null;
  fileName: string | null;
  fileSize: number | null;
  fileMime: string | null;
  ipHash: string;
};

/** Кладёт документ в приватный бакет. Возвращает путь внутри бакета. */
export async function uploadSubmissionFile(
  submissionId: string,
  fileName: string,
  bytes: ArrayBuffer,
  mime: string,
): Promise<string> {
  const path = `${submissionId}/${safeFileName(fileName)}`;

  const { error } = await supabaseAdmin()
    .storage.from(SUBMISSIONS_BUCKET)
    .upload(path, bytes, { contentType: mime, upsert: false });

  if (error) {
    throw new Error(`Не удалось сохранить файл: ${error.message}`);
  }

  return path;
}

export async function createSubmission(input: NewSubmission): Promise<SubmissionRow> {
  const { data, error } = await supabaseAdmin()
    .from("submissions")
    .insert({
      id: input.id,
      author_name: input.authorName,
      author_email: input.authorEmail,
      author_contact: input.authorContact,
      title: input.title,
      company: input.company,
      summary: input.summary,
      external_url: input.externalUrl,
      file_path: input.filePath,
      file_name: input.fileName,
      file_size: input.fileSize,
      file_mime: input.fileMime,
      ip_hash: input.ipHash,
    })
    .select()
    .single<SubmissionRow>();

  if (error) {
    throw new Error(`Не удалось сохранить заявку: ${error.message}`);
  }

  return data;
}

export async function rememberTelegramMessage(
  id: string,
  messageId: number,
): Promise<void> {
  const { error } = await supabaseAdmin()
    .from("submissions")
    .update({ telegram_message_id: messageId })
    .eq("id", id);

  if (error) {
    console.error("[submissions] не записал id сообщения Telegram:", error.message);
  }
}

export async function getSubmissionById(id: string): Promise<SubmissionRow | null> {
  const { data, error } = await supabaseAdmin()
    .from("submissions")
    .select()
    .eq("id", id)
    .maybeSingle<SubmissionRow>();

  if (error) {
    throw new Error(`Не удалось прочитать заявку: ${error.message}`);
  }

  return data;
}

/** Опубликованные кейсы от читателей, свежие сверху. */
export async function getApprovedSubmissions(): Promise<readonly SubmissionRow[]> {
  const { data, error } = await supabaseAdmin()
    .from("submissions")
    .select()
    .eq("status", "approved")
    .order("published_at", { ascending: false })
    .returns<SubmissionRow[]>();

  if (error) {
    console.error("[submissions] не удалось получить список:", error.message);
    return [];
  }

  return data ?? [];
}

/**
 * Меняет статус заявки. Меняет только те, что ещё ждут решения,
 * поэтому повторное нажатие кнопки ничего не ломает.
 */
export async function decideSubmission(
  id: string,
  status: Exclude<SubmissionStatus, "pending">,
): Promise<SubmissionRow | null> {
  const now = new Date().toISOString();

  const { data, error } = await supabaseAdmin()
    .from("submissions")
    .update({
      status,
      reviewed_at: now,
      published_at: status === "approved" ? now : null,
    })
    .eq("id", id)
    .eq("status", "pending")
    .select()
    .maybeSingle<SubmissionRow>();

  if (error) {
    throw new Error(`Не удалось обновить заявку: ${error.message}`);
  }

  return data;
}

/** Временная ссылка на приватный файл. */
export async function createSignedFileUrl(path: string): Promise<string> {
  const { data, error } = await supabaseAdmin()
    .storage.from(SUBMISSIONS_BUCKET)
    .createSignedUrl(path, SIGNED_URL_TTL_SECONDS);

  if (error || !data) {
    throw new Error(`Не удалось создать ссылку на файл: ${error?.message}`);
  }

  return data.signedUrl;
}
