import { randomUUID } from "node:crypto";

import { NextResponse } from "next/server";

import { checkRateLimit, clientIp, hashIp } from "@/lib/rate-limit";
import {
  createSubmission,
  rememberTelegramMessage,
  uploadSubmissionFile,
} from "@/lib/submissions";
import { sendSubmissionCard, sendSubmissionDocument } from "@/lib/telegram";
import { checkFile, looksLikeBot, submissionFieldsSchema } from "@/lib/validation";

export const runtime = "nodejs";

type FieldErrors = Record<string, string>;

function badRequest(message: string, fields: FieldErrors = {}) {
  return NextResponse.json({ ok: false, message, fields }, { status: 400 });
}

function text(form: FormData, key: string): string {
  const value = form.get(key);
  return typeof value === "string" ? value : "";
}

export async function POST(request: Request) {
  let form: FormData;
  try {
    form = await request.formData();
  } catch {
    return badRequest("Не удалось прочитать форму. Попробуйте ещё раз.");
  }

  // Ловушка для ботов: скрытое поле должно остаться пустым.
  // Заполнено — делаем вид, что всё прошло, и ничего не сохраняем.
  const honeypot = text(form, "website");
  const elapsedMs = Date.now() - Number(text(form, "startedAt") || 0);

  if (honeypot.trim().length > 0) {
    return NextResponse.json({ ok: true, id: null });
  }
  if (looksLikeBot("", elapsedMs)) {
    return badRequest("Форма отправлена слишком быстро. Проверьте поля и нажмите ещё раз.");
  }

  const parsed = submissionFieldsSchema.safeParse({
    authorName: text(form, "authorName"),
    authorEmail: text(form, "authorEmail"),
    authorContact: text(form, "authorContact"),
    title: text(form, "title"),
    company: text(form, "company"),
    summary: text(form, "summary"),
    externalUrl: text(form, "externalUrl"),
    consent: text(form, "consent") === "on" || text(form, "consent") === "true",
  });

  if (!parsed.success) {
    const fields: FieldErrors = {};
    for (const issue of parsed.error.issues) {
      const key = String(issue.path[0] ?? "");
      if (key && !fields[key]) fields[key] = issue.message;
    }
    return badRequest("Проверьте отмеченные поля.", fields);
  }

  const fields = parsed.data;
  const upload = form.get("file");
  const file = upload instanceof File && upload.size > 0 ? upload : null;
  const externalUrl = fields.externalUrl || null;

  if (!file && !externalUrl) {
    return badRequest("Приложите файл или дайте ссылку на документ.", {
      externalUrl: "нужна ссылка или файл",
    });
  }

  if (file) {
    const check = checkFile(file.name, file.size, file.type);
    if (!check.ok) {
      return badRequest("С файлом что-то не так.", { file: check.message });
    }
  }

  let ipHash: string;
  try {
    ipHash = hashIp(clientIp(request.headers));
  } catch (error) {
    console.error("[submissions] окружение не настроено:", error);
    return NextResponse.json(
      { ok: false, message: "Приём заявок временно не работает." },
      { status: 503 },
    );
  }

  const limit = await checkRateLimit(ipHash);
  if (!limit.allowed) {
    return NextResponse.json(
      {
        ok: false,
        message: "Слишком много заявок с одного адреса. Попробуйте через час.",
      },
      { status: 429 },
    );
  }

  const id = randomUUID();

  try {
    let filePath: string | null = null;
    let bytes: ArrayBuffer | null = null;

    if (file) {
      bytes = await file.arrayBuffer();
      filePath = await uploadSubmissionFile(id, file.name, bytes, file.type);
    }

    await createSubmission({
      id,
      authorName: fields.authorName,
      authorEmail: fields.authorEmail,
      authorContact: fields.authorContact || null,
      title: fields.title,
      company: fields.company || null,
      summary: fields.summary,
      externalUrl,
      filePath,
      fileName: file?.name ?? null,
      fileSize: file?.size ?? null,
      fileMime: file?.type ?? null,
      ipHash,
    });

    // Заявка уже сохранена. Если Telegram не ответит — это не повод
    // показывать человеку ошибку: его работа сделана, разберёмся на нашей стороне.
    try {
      const messageId = await sendSubmissionCard({
        id,
        title: fields.title,
        authorName: fields.authorName,
        authorEmail: fields.authorEmail,
        authorContact: fields.authorContact || null,
        company: fields.company || null,
        summary: fields.summary,
        externalUrl,
        fileName: file?.name ?? null,
      });

      await rememberTelegramMessage(id, messageId);

      if (file && bytes) {
        await sendSubmissionDocument(bytes, file.name, file.type, messageId);
      }
    } catch (error) {
      console.error("[submissions] не смог уведомить в Telegram:", error);
    }

    return NextResponse.json({ ok: true, id });
  } catch (error) {
    console.error("[submissions] заявка не сохранена:", error);
    return NextResponse.json(
      { ok: false, message: "Не получилось сохранить заявку. Попробуйте позже." },
      { status: 500 },
    );
  }
}
