import { timingSafeEqual } from "node:crypto";

import { NextResponse } from "next/server";

import { serverEnv, siteUrl } from "@/lib/env";
import { decideSubmission, getSubmissionById } from "@/lib/submissions";
import { answerCallbackQuery, editCard } from "@/lib/telegram";
import { buildDecisionText, parseCallbackData } from "@/lib/telegram-message";

export const runtime = "nodejs";

type CallbackQuery = {
  id: string;
  data?: string;
  from?: { id?: number };
  message?: { message_id?: number; text?: string };
};

/** Сравнение секретов без утечки через время ответа. */
function secretMatches(received: string | null, expected: string): boolean {
  if (!received) return false;
  const a = Buffer.from(received);
  const b = Buffer.from(expected);
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

export async function POST(request: Request) {
  let env;
  try {
    env = serverEnv();
  } catch (error) {
    console.error("[telegram] окружение не настроено:", error);
    return NextResponse.json({ ok: false }, { status: 503 });
  }

  if (
    !secretMatches(
      request.headers.get("x-telegram-bot-api-secret-token"),
      env.TELEGRAM_WEBHOOK_SECRET,
    )
  ) {
    // Эндпоинт открыт наружу, поэтому чужие запросы отбиваем молча.
    return NextResponse.json({ ok: false }, { status: 401 });
  }

  let update: { callback_query?: CallbackQuery };
  try {
    update = await request.json();
  } catch {
    return NextResponse.json({ ok: true });
  }

  const query = update.callback_query;
  if (!query) return NextResponse.json({ ok: true });

  // Кнопки работают только у владельца сайта.
  if (String(query.from?.id ?? "") !== env.TELEGRAM_ADMIN_USER_ID) {
    await answerCallbackQuery(query.id, "Эти кнопки не для вас.").catch(() => {});
    return NextResponse.json({ ok: true });
  }

  const parsed = query.data ? parseCallbackData(query.data) : null;
  if (!parsed) {
    await answerCallbackQuery(query.id, "Не понял команду.").catch(() => {});
    return NextResponse.json({ ok: true });
  }

  try {
    const status = parsed.action === "approve" ? "approved" : "rejected";
    const updated = await decideSubmission(parsed.id, status);

    if (!updated) {
      // Заявку уже разобрали раньше — второе нажатие ничего не меняет.
      const existing = await getSubmissionById(parsed.id);
      await answerCallbackQuery(
        query.id,
        existing ? "Решение уже принято." : "Заявка не найдена.",
      );
      return NextResponse.json({ ok: true });
    }

    const messageId = query.message?.message_id;
    if (messageId) {
      const publicUrl =
        status === "approved" ? `${siteUrl()}/cases/shared/${updated.id}` : null;
      await editCard(
        messageId,
        buildDecisionText(query.message?.text ?? updated.title, status, publicUrl),
      );
    }

    await answerCallbackQuery(
      query.id,
      status === "approved" ? "Опубликовано" : "Отклонено",
    );
  } catch (error) {
    console.error("[telegram] не смог обработать нажатие:", error);
    await answerCallbackQuery(query.id, "Что-то пошло не так.").catch(() => {});
  }

  return NextResponse.json({ ok: true });
}
