import { NextResponse } from "next/server";

import { createSignedFileUrl, getSubmissionById } from "@/lib/submissions";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Отдаёт присланный документ. Файл лежит в приватном бакете,
 * поэтому наружу уходит временная подписанная ссылка — и только
 * для заявок, которые прошли модерацию.
 */
export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;

  if (!UUID.test(id)) {
    return new NextResponse("Не найдено", { status: 404 });
  }

  try {
    const submission = await getSubmissionById(id);

    if (!submission || submission.status !== "approved" || !submission.file_path) {
      return new NextResponse("Не найдено", { status: 404 });
    }

    const url = await createSignedFileUrl(submission.file_path);
    return NextResponse.redirect(url, { status: 302 });
  } catch (error) {
    console.error("[file] не смог отдать файл:", error);
    return new NextResponse("Файл временно недоступен", { status: 503 });
  }
}
EOF
