cat > tests/validation.test.ts <<'EOF'
import { describe, expect, it } from "vitest";

import {
  checkFile,
  looksLikeBot,
  MAX_FILE_BYTES,
  submissionFieldsSchema,
} from "@/lib/validation";

const PDF = "application/pdf";
const DOCX =
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

describe("checkFile", () => {
  it("принимает pdf и docx", () => {
    expect(checkFile("case.pdf", 1000, PDF)).toEqual({ ok: true, extension: ".pdf" });
    expect(checkFile("Кейс.DOCX", 1000, DOCX)).toEqual({ ok: true, extension: ".docx" });
  });

  it("принимает файл, у которого браузер не определил тип", () => {
    expect(checkFile("case.docx", 1000, "application/octet-stream").ok).toBe(true);
    expect(checkFile("case.docx", 1000, "").ok).toBe(true);
  });

  it("отклоняет чужие расширения", () => {
    expect(checkFile("script.exe", 1000, "application/octet-stream").ok).toBe(false);
    expect(checkFile("photo.png", 1000, "image/png").ok).toBe(false);
    expect(checkFile("noextension", 1000, PDF).ok).toBe(false);
  });

  it("отклоняет подмену типа под расширением", () => {
    expect(checkFile("case.pdf", 1000, "image/png").ok).toBe(false);
  });

  it("следит за размером", () => {
    expect(checkFile("case.pdf", 0, PDF).ok).toBe(false);
    expect(checkFile("case.pdf", MAX_FILE_BYTES + 1, PDF).ok).toBe(false);
    expect(checkFile("case.pdf", MAX_FILE_BYTES, PDF).ok).toBe(true);
  });

  it("не спотыкается о параметры в типе", () => {
    expect(checkFile("case.pdf", 1000, "application/pdf; charset=binary").ok).toBe(true);
  });
});

describe("looksLikeBot", () => {
  it("ловит заполненную ловушку", () => {
    expect(looksLikeBot("я бот", 99_000)).toBe(true);
  });

  it("ловит мгновенную отправку", () => {
    expect(looksLikeBot("", 100)).toBe(true);
  });

  it("пропускает живого человека", () => {
    expect(looksLikeBot("", 30_000)).toBe(false);
  });
});

const validFields = {
  authorName: "Пётр Иванов",
  authorEmail: "petr@example.com",
  authorContact: "@petr",
  title: "Как мы удвоили конверсию",
  company: "Маркетплейс",
  summary: "Тестовое задание про рост выручки в SMB-сегменте маркетплейса.",
  externalUrl: "https://docs.google.com/document/d/abc",
  consent: true,
} as const;

describe("submissionFieldsSchema", () => {
  it("пропускает корректную заявку", () => {
    expect(submissionFieldsSchema.safeParse(validFields).success).toBe(true);
  });

  it("разрешает пустые необязательные поля", () => {
    const result = submissionFieldsSchema.safeParse({
      ...validFields,
      authorContact: "",
      company: "",
      externalUrl: "",
    });
    expect(result.success).toBe(true);
  });

  it("требует согласие на публикацию", () => {
    const result = submissionFieldsSchema.safeParse({ ...validFields, consent: false });
    expect(result.success).toBe(false);
  });

