input.command:
cat > src/lib/file-name.ts <<'EOF'
/**
 * Приводит имя файла к безопасному виду для хранилища: только латиница,
 * цифры, дефис и подчёркивание, плюс исходное расширение.
 *
 * Исходное имя от этого не теряется — оно остаётся в базе (file_name)
 * и показывается в карточке заявки.
 */
export function safeFileName(name: string): string {
  const dot = name.lastIndexOf(".");

  const base = (dot > 0 ? name.slice(0, dot) : name)
    .normalize("NFKD")
    .replace(/[^A-Za-z0-9_-]+/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);

  const extension = (dot > 0 ? name.slice(dot) : "")
    .toLowerCase()
    .replace(/[^a-z0-9.]/g, "");

  return `${base || "document"}${extension}`;
}
EOF
npx vitest run --reporter=dot 2>&1 | tail -10

