cat > tests/cases.test.ts <<'EOF'
import { describe, expect, it } from "vitest";

import { getAllSlugs, getCaseBySlug, getPublicCases } from "@/lib/cases";

describe("чтение кейсов из папки content", () => {
  it("находит кейсы на диске", async () => {
    const slugs = await getAllSlugs();
    expect(slugs.length).toBeGreaterThan(0);
  });

  it("не показывает скрытые кейсы в списке", async () => {
    const slugs = await getAllSlugs();
    const publicCases = await getPublicCases();
    const publicSlugs = publicCases.map((item) => item.slug);

    expect(slugs).toContain("loyalty-betting-7b3f21");
    expect(publicSlugs).not.toContain("loyalty-betting-7b3f21");
  });

  it("скрытый кейс всё равно открывается по прямой ссылке", async () => {
    const entry = await getCaseBySlug("loyalty-betting-7b3f21");
    expect(entry?.visibility).toBe("unlisted");
    expect(entry?.body.length).toBeGreaterThan(0);
  });

  it("сортирует список от свежих к старым", async () => {
    const publicCases = await getPublicCases();
    const periods = publicCases.map((item) => item.period);
    expect([...periods].sort().reverse()).toEqual(periods);
  });

  it("возвращает null на несуществующий кейс", async () => {
    expect(await getCaseBySlug("нет-такого")).toBeNull();
    expect(await getCaseBySlug("missing-case")).toBeNull();
  });

  it("не даёт выйти за пределы папки через слаг", async () => {
    expect(await getCaseBySlug("../../../etc/passwd")).toBeNull();
    expect(await getCaseBySlug("..")).toBeNull();
  });
});
