                  href={link.href}
                  className="text-ink-muted transition-colors hover:text-accent"
                  style={{ fontSize: "var(--text-sm)" }}
                >
                  {link.label}
                </Link>
              </li>
            ))}
          </ul>
        </nav>
      </Container>
    </header>
  );
}
