cat > src/components/case/CaseCard.tsx <<'EOF'
import Link from "next/link";

import type { CaseMeta } from "@/lib/cases";
import { formatPeriod } from "@/lib/format";

/** Карточка кейса в списке. Ссылка накрывает всю карточку. */
export function CaseCard({ item }: { item: CaseMeta }) {
  return (
    <article className="group relative flex flex-col gap-3 border-t border-line pt-6">
      <div
        className="flex flex-wrap items-baseline gap-x-3 gap-y-1 text-ink-muted"
        style={{ fontSize: "var(--text-xs)" }}
      >
        <time dateTime={item.period}>{formatPeriod(item.period)}</time>
        {item.company ? <span>· {item.company}</span> : null}
        {item.outcome ? (
          <span className="text-accent">· {item.outcome}</span>
        ) : null}
      </div>

      <h3
        className="font-display text-ink"
        style={{ fontSize: "var(--text-xl)", lineHeight: "var(--leading-snug)" }}
      >
        <Link
          href={`/cases/${item.slug}`}
          className="transition-colors before:absolute before:inset-0 before:content-[''] group-hover:text-accent"
        >
          {item.title}
        </Link>
      </h3>

      <p className="text-ink-muted" style={{ fontSize: "var(--text-sm)" }}>
        {item.summary}
      </p>

      {item.tags.length > 0 ? (
        <ul className="flex flex-wrap gap-2" style={{ fontSize: "var(--text-xs)" }}>
          {item.tags.map((tag) => (
            <li
              key={tag}
              className="rounded-sm border border-line px-2 py-0.5 text-ink-muted"
            >
              {tag}
            </li>
          ))}
        </ul>
      ) : null}
    </article>
  );
}
EOF
cat > src/lib/format.ts <<'EOF'
const MONTHS = [
  "январь", "февраль", "март", "апрель", "май", "июнь",
  "июль", "август", "сентябрь", "октябрь", "ноябрь", "декабрь",
] as const;

/** «2026-08» → «август 2026». */
export function formatPeriod(period: string): string {
  const [year, month] = period.split("-");
  const index = Number(month) - 1;
  const name = MONTHS[index];
  return name ? `${name} ${year}` : period;
}

/** «2026-09-17T10:00:00Z» → «17 сентября 2026». */
export function formatDate(iso: string | null): string {
  if (!iso) return "";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("ru-RU", {
    day: "numeric",
    month: "long",
    year: "numeric",
    timeZone: "UTC",
  }).format(date);
}
EOF
cat > tests/format.test.ts <<'EOF'
import { describe, expect, it } from "vitest";

import { formatDate, formatPeriod } from "@/lib/format";

describe("formatPeriod", () => {
  it("переводит месяц в слово", () => {
    expect(formatPeriod("2026-08")).toBe("август 2026");
    expect(formatPeriod("2026-01")).toBe("январь 2026");
    expect(formatPeriod("2026-12")).toBe("декабрь 2026");
  });

  it("возвращает исходное значение, если формат неожиданный", () => {
    expect(formatPeriod("2026-13")).toBe("2026-13");
    expect(formatPeriod("ерунда")).toBe("ерунда");
  });
});

describe("formatDate", () => {
  it("форматирует дату по-русски", () => {
    expect(formatDate("2026-09-17T10:00:00Z")).toBe("17 сентября 2026 г.");
  });

  it("не падает на пустом и кривом значении", () => {
    expect(formatDate(null)).toBe("");
    expect(formatDate("не дата")).toBe("");
  });
});
EOF
