type FieldErrors = Record<string, string>;

export function SubmitForm() {
  const router = useRouter();
  const startedAt = useRef<number>(0);

  const [pending, setPending] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});

  // Отметка времени: форма, заполненная мгновенно, почти наверняка от бота.
  useEffect(() => {
    startedAt.current = Date.now();
  }, []);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pending) return;

    setPending(true);
    setFormError(null);
    setFieldErrors({});

    const form = new FormData(event.currentTarget);
    form.set("startedAt", String(startedAt.current));

    const file = form.get("file");
    if (file instanceof File && file.size > MAX_FILE_BYTES) {
      setFieldErrors({ file: "файл больше 20 МБ" });
      setPending(false);
      return;
    }

    try {
      const response = await fetch("/api/submissions", {
        method: "POST",
        body: form,
      });
      const result = (await response.json()) as {
        ok: boolean;
        message?: string;
        fields?: FieldErrors;
      };

      if (!response.ok || !result.ok) {
        setFormError(result.message ?? "Не получилось отправить. Попробуйте ещё раз.");
        setFieldErrors(result.fields ?? {});
        setPending(false);
        return;
      }

      router.push("/submit/thanks");
    } catch {
      setFormError("Нет связи с сервером. Проверьте интернет и попробуйте ещё раз.");
      setPending(false);
