        <legend className="sr-only">О вас</legend>

        <div className="grid gap-6 sm:grid-cols-2">
          <Field id="authorName" label="Как вас зовут" error={fieldErrors.authorName}>
            <input
              id="authorName"
              name="authorName"
              type="text"
              required
              autoComplete="name"
              className={inputClass}
              aria-invalid={invalid("authorName")}
              aria-describedby={describedBy("authorName")}
            />
          </Field>

          <Field
            id="authorEmail"
            label="Почта"
            hint="Нужна, чтобы ответить по вашему кейсу"
            error={fieldErrors.authorEmail}
          >
            <input
              id="authorEmail"
              name="authorEmail"
              type="email"
              required
              autoComplete="email"
              className={inputClass}
              aria-invalid={invalid("authorEmail")}
              aria-describedby={describedBy("authorEmail")}
            />
          </Field>
        </div>

        <Field
          id="authorContact"
          label="Другой контакт"
          hint="Телеграм или ссылка на профиль — по желанию"
          error={fieldErrors.authorContact}
        >
          <input
            id="authorContact"
            name="authorContact"
            type="text"
            className={inputClass}
            aria-invalid={invalid("authorContact")}
            aria-describedby={describedBy("authorContact")}
          />
        </Field>
      </fieldset>

      <fieldset className="flex flex-col gap-6 border-t border-line pt-8">
        <legend className="sr-only">О кейсе</legend>

        <Field id="title" label="Название кейса" error={fieldErrors.title}>
          <input
            id="title"
            name="title"
            type="text"
            required
            className={inputClass}
            aria-invalid={invalid("title")}
            aria-describedby={describedBy("title")}
          />
        </Field>

        <Field
          id="company"
          label="Компания или продукт"
          hint="Можно обезличить, если мешает NDA"
          error={fieldErrors.company}
        >
          <input
            id="company"
