          <input
            name="consent"
            type="checkbox"
            required
            className="mt-1 h-4 w-4 shrink-0 accent-[var(--accent)]"
            aria-invalid={invalid("consent")}
          />
          <span>
            Я автор этого материала и не против, чтобы он появился на сайте.
          </span>
        </label>
        {fieldErrors.consent ? (
          <p role="alert" className="mt-2 text-danger" style={{ fontSize: "var(--text-xs)" }}>
