"use client";

import { useRouter } from "next/navigation";
import { useEffect, useRef, useState, type FormEvent } from "react";

import { ALLOWED_EXTENSIONS, MAX_FILE_BYTES } from "@/lib/validation";

import { Field, inputClass } from "./Field";

type FieldErrors = Record<string, string>;

export function SubmitForm() {
  const router = useRouter();
  const startedAt = useRef<number>(0);

  const [pending, setPending] = useState(false);
  const [formError, setFormError] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<FieldErrors>({});

  // Отметка времени: форма, заполненная мгновенно, почти наверняка от бота.
  useEffect(() => {
    startedAt.current = Date.now();
  }, []);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pending) return;

    setPending(true);
    setFormError(null);
    setFieldErrors({});

    const form = new FormData(event.currentTarget);
    form.set("startedAt", String(startedAt.current));

    const file = form.get("file");
    if (file instanceof File && file.size > MAX_FILE_BYTES) {
      setFieldErrors({ file: "файл больше 20 МБ" });
      setPending(false);
      return;
    }

    try {
      const response = await fetch("/api/submissions", {
        method: "POST",
        body: form,
      });
      const result = (await response.json()) as {
        ok: boolean;
        message?: string;
        fields?: FieldErrors;
      };

      if (!response.ok || !result.ok) {
        setFormError(result.message ?? "Не получилось отправить. Попробуйте ещё раз.");
        setFieldErrors(result.fields ?? {});
        setPending(false);
        return;
      }

      router.push("/submit/thanks");
    } catch {
      setFormError("Нет связи с сервером. Проверьте интернет и попробуйте ещё раз.");
      setPending(false);
    }
  }

  const invalid = (name: string) => (fieldErrors[name] ? true : undefined);
  const describedBy = (name: string) =>
    fieldErrors[name] ? `${name}-error` : undefined;

  return (
    <form
      onSubmit={handleSubmit}
      noValidate
      className="mt-12 flex flex-col gap-8"
      style={{ maxWidth: "44rem" }}
    >
      {/* Ловушка для ботов: настоящие люди это поле не видят и не заполняют. */}
      <div aria-hidden="true" className="absolute h-px w-px overflow-hidden opacity-0">
        <label htmlFor="website">Не заполняйте это поле</label>
        <input id="website" name="website" type="text" tabIndex={-1} autoComplete="off" />
      </div>

      <fieldset className="flex flex-col gap-6">
        <legend className="sr-only">О вас</legend>

        <div className="grid gap-6 sm:grid-cols-2">
          <Field id="authorName" label="Как вас зовут" error={fieldErrors.authorName}>
            <input
              id="authorName"
              name="authorName"
              type="text"
              required
              autoComplete="name"
              className={inputClass}
              aria-invalid={invalid("authorName")}
              aria-describedby={describedBy("authorName")}
            />
          </Field>

          <Field
            id="authorEmail"
            label="Почта"
            hint="Нужна, чтобы ответить по вашему кейсу"
            error={fieldErrors.authorEmail}
          >
            <input
              id="authorEmail"
              name="authorEmail"
              type="email"
              required
              autoComplete="email"
              className={inputClass}
              aria-invalid={invalid("authorEmail")}
              aria-describedby={describedBy("authorEmail")}
            />
          </Field>
        </div>

        <Field
          id="authorContact"
          label="Другой контакт"
          hint="Телеграм или ссылка на профиль — по желанию"
          error={fieldErrors.authorContact}
        >
          <input
            id="authorContact"
            name="authorContact"
            type="text"
            className={inputClass}
            aria-invalid={invalid("authorContact")}
            aria-describedby={describedBy("authorContact")}
          />
        </Field>
      </fieldset>

      <fieldset className="flex flex-col gap-6 border-t border-line pt-8">
        <legend className="sr-only">О кейсе</legend>

        <Field id="title" label="Название кейса" error={fieldErrors.title}>
          <input
            id="title"
            name="title"
            type="text"
            required
            className={inputClass}
            aria-invalid={invalid("title")}
            aria-describedby={describedBy("title")}
          />
        </Field>

        <Field
          id="company"
          label="Компания или продукт"
          hint="Можно обезличить, если мешает NDA"
          error={fieldErrors.company}
        >
          <input
            id="company"
            name="company"
            type="text"
            className={inputClass}
            aria-invalid={invalid("company")}
            aria-describedby={describedBy("company")}
          />
        </Field>

        <Field
          id="summary"
          label="О чём кейс"
          hint="Пара предложений: какая была задача и к чему пришли"
          error={fieldErrors.summary}
        >
          <textarea
            id="summary"
            name="summary"
            required
            rows={5}
            maxLength={1000}
            className={`${inputClass} resize-y`}
            aria-invalid={invalid("summary")}
            aria-describedby={describedBy("summary")}
          />
        </Field>
      </fieldset>

      <fieldset className="flex flex-col gap-6 border-t border-line pt-8">
        <legend className="mb-2 text-ink" style={{ fontSize: "var(--text-sm)" }}>
          Сам документ — достаточно чего-то одного
        </legend>

        <Field
          id="externalUrl"
          label="Ссылка на документ"
          hint="Google Docs, Notion или другой открытый доступ по ссылке"
          error={fieldErrors.externalUrl}
        >
          <input
            id="externalUrl"
            name="externalUrl"
            type="url"
            placeholder="https://docs.google.com/document/d/..."
            className={inputClass}
            aria-invalid={invalid("externalUrl")}
            aria-describedby={describedBy("externalUrl")}
          />
        </Field>

        <Field
          id="file"
          label="Или файл"
          hint={`${ALLOWED_EXTENSIONS.join(", ")} — до 20 МБ`}
          error={fieldErrors.file}
        >
          <input
            id="file"
            name="file"
            type="file"
            accept={ALLOWED_EXTENSIONS.join(",")}
            className="w-full text-ink file:mr-4 file:border file:border-line file:bg-surface file:px-4 file:py-2 file:text-ink file:transition-colors hover:file:border-accent"
            style={{ fontSize: "var(--text-sm)" }}
            aria-invalid={invalid("file")}
            aria-describedby={describedBy("file")}
          />
        </Field>
      </fieldset>

      <div className="border-t border-line pt-8">
        <label className="flex items-start gap-3 text-ink" style={{ fontSize: "var(--text-sm)" }}>
          <input
            name="consent"
            type="checkbox"
            required
            className="mt-1 h-4 w-4 shrink-0 accent-[var(--accent)]"
            aria-invalid={invalid("consent")}
          />
          <span>
            Я автор этого материала и не против, чтобы он появился на сайте.
          </span>
        </label>
        {fieldErrors.consent ? (
          <p role="alert" className="mt-2 text-danger" style={{ fontSize: "var(--text-xs)" }}>
            {fieldErrors.consent}
          </p>
        ) : null}
      </div>

      {formError ? (
        <p
          role="alert"
          className="border border-danger px-4 py-3 text-danger"
          style={{ borderRadius: "var(--radius-sm)", fontSize: "var(--text-sm)" }}
        >
          {formError}
        </p>
      ) : null}

      <div>
        <button
          type="submit"
          disabled={pending}
          className="border border-accent px-6 py-3 text-accent transition-colors hover:bg-accent hover:text-paper disabled:cursor-not-allowed disabled:opacity-50"
          style={{ borderRadius: "var(--radius-sm)", fontSize: "var(--text-sm)" }}
        >
          {pending ? "Отправляю…" : "Отправить на проверку"}
        </button>
      </div>
    </form>
  );
}
