input.command:
cat > scripts/setup-telegram-webhook.ts <<'EOF'
/**
 * Разовая настройка вебхука Telegram.
 *
 *   pnpm telegram:webhook https://ваш-сайт.vercel.app
 *   pnpm telegram:webhook --delete      — отключить
 *   pnpm telegram:webhook --info        — показать текущее состояние
 *
 * Адрес можно не указывать: возьмётся NEXT_PUBLIC_SITE_URL из .env.local.
 */
import { config } from "dotenv";

config({ path: ".env.local", quiet: true });

const token = process.env.TELEGRAM_BOT_TOKEN;
const secret = process.env.TELEGRAM_WEBHOOK_SECRET;

if (!token || !secret) {
  console.error("Нет TELEGRAM_BOT_TOKEN или TELEGRAM_WEBHOOK_SECRET в .env.local");
  process.exit(1);
}

const api = (method: string) => `https://api.telegram.org/bot${token}/${method}`;

async function call(method: string, payload: Record<string, unknown> = {}) {
  const response = await fetch(api(method), {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(payload),
  });
  const json = (await response.json()) as {
    ok: boolean;
    result?: unknown;
    description?: string;
  };
  if (!json.ok) throw new Error(`${method}: ${json.description}`);
  return json.result;
}

const arg = process.argv[2];

if (arg === "--info") {
  console.log(await call("getWebhookInfo"));
  process.exit(0);
}

if (arg === "--delete") {
  await call("deleteWebhook", { drop_pending_updates: true });
  console.log("Вебхук отключён.");
  process.exit(0);
}

const base = (arg ?? process.env.NEXT_PUBLIC_SITE_URL ?? "").replace(/\/$/, "");

if (!base.startsWith("https://")) {
  console.error(
    `Нужен адрес по https. Получено: ${base || "(пусто)"}\n` +
      "Telegram не умеет слать вебхуки на localhost — для локальной проверки\n" +
      "поднимите туннель (ngrok, cloudflared) и передайте его адрес.",
  );
  process.exit(1);
}

const url = `${base}/api/telegram/webhook`;

await call("setWebhook", {
  url,
  secret_token: secret,
  allowed_updates: ["callback_query"],
  drop_pending_updates: true,
});

console.log(`Вебхук установлен: ${url}`);
EOF
cat > playwright.config.ts <<'EOF'
import { defineConfig, devices } from "@playwright/test";

const PORT = 3100;
const baseURL = `http://127.0.0.1:${PORT}`;

export default defineConfig({
  testDir: "./e2e",
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: process.env.CI ? 1 : 0,
  reporter: process.env.CI ? "github" : "list",

  use: {
    baseURL,
    trace: "on-first-retry",
    screenshot: "only-on-failure",
    locale: "ru-RU",
  },

  projects: [
    { name: "chromium", use: { ...devices["Desktop Chrome"] } },
    { name: "mobile", use: { ...devices["iPhone 13"] } },
  ],

  webServer: {
    command: `pnpm build && pnpm start --port ${PORT}`,
    url: baseURL,
    reuseExistingServer: !process.env.CI,
    timeout: 180_000,
  },
});
EOF
