import { expect, test } from "@playwright/test";

const UNLISTED = "loyalty-betting-7b3f21";
const PUBLIC = "smb-gig-platform";

test("главная показывает кейсы", async ({ page }) => {
  await page.goto("/");

  await expect(page.getByRole("heading", { level: 1 })).toBeVisible();
  await expect(page.getByRole("heading", { name: "Мои кейсы" })).toBeVisible();
  await expect(page.getByRole("link", { name: /Стратегия SMB/ })).toBeVisible();
});

test("кейс открывается со страницы списка", async ({ page }) => {
  await page.goto("/");
  await page.getByRole("link", { name: /Стратегия SMB/ }).click();

  await expect(page).toHaveURL(new RegExp(`/cases/${PUBLIC}$`));
  await expect(page.getByRole("heading", { level: 1 })).toContainText("Стратегия SMB");
});

test("скрытого кейса нет в списке, но он открывается по прямой ссылке", async ({
  page,
}) => {
  await page.goto("/");
  await expect(page.getByRole("link", { name: /Программа лояльности/ })).toHaveCount(0);

  const response = await page.goto(`/cases/${UNLISTED}`);
  expect(response?.status()).toBe(200);
  await expect(page.getByRole("heading", { level: 1 })).toContainText(
    "Программа лояльности",
  );
  await expect(page.locator('meta[name="robots"]')).toHaveAttribute(
    "content",
    /noindex/,
  );
});

test("скрытого кейса нет в карте сайта", async ({ request }) => {
  const response = await request.get("/sitemap.xml");
  const xml = await response.text();

  expect(xml).toContain(`/cases/${PUBLIC}`);
  expect(xml).not.toContain(UNLISTED);
});

test("несуществующий кейс отдаёт 404", async ({ page }) => {
  const response = await page.goto("/cases/no-such-case");
  expect(response?.status()).toBe(404);
});

test("страница «обо мне» открывается", async ({ page }) => {
  await page.goto("/about");
  await expect(page.getByRole("heading", { name: "Обо мне" })).toBeVisible();
});

test("файл неодобренной заявки не отдаётся", async ({ request }) => {
  const response = await request.get(
    "/api/submissions/00000000-0000-4000-8000-000000000000/file",
  );
  expect(response.status()).toBe(404);
});

test("вебхук Telegram отбивает запрос без секрета", async ({ request }) => {
  const response = await request.post("/api/telegram/webhook", {
    data: { callback_query: { id: "1", data: "approve:x" } },
  });
  expect(response.status()).toBe(401);
});
EOF
cat > e2e/submit.spec.ts <<'EOF'
import { expect, test } from "@playwright/test";

/** Ждём, пока пройдёт защита от слишком быстрой отправки. */
async function waitOutBotGuard(page: import("@playwright/test").Page) {
  await page.waitForTimeout(3200);
}

async function fillRequired(page: import("@playwright/test").Page) {
  await page.getByLabel("Как вас зовут").fill("Пётр Иванов");
  await page.getByLabel("Почта", { exact: true }).fill("petr@example.com");
  await page.getByLabel("Название кейса").fill("Рост выручки в SMB");
  await page
    .getByLabel("О чём кейс")
    .fill("Тестовое задание про рост выручки в сегменте малого бизнеса.");
  await page.getByRole("checkbox").check();
}

test("форма отправки открывается", async ({ page }) => {
  await page.goto("/submit");
  await expect(page.getByRole("heading", { level: 1 })).toContainText(
    "Прислать свой кейс",
  );
  await expect(page.getByRole("button", { name: /Отправить/ })).toBeVisible();
});

test("пустая форма не отправляется и показывает, что исправить", async ({ page }) => {
  await page.goto("/submit");
  await waitOutBotGuard(page);

  await page.getByRole("button", { name: /Отправить/ }).click();

  await expect(page.getByRole("alert").first()).toBeVisible();
  await expect(page).toHaveURL(/\/submit$/);
});

test("без ссылки и файла форма не проходит", async ({ page }) => {
  await page.goto("/submit");
  await waitOutBotGuard(page);

  await fillRequired(page);
  await page.getByRole("button", { name: /Отправить/ }).click();

  await expect(page.getByText("Приложите файл или дайте ссылку")).toBeVisible();
});

test("опасная ссылка не принимается", async ({ page }) => {
  await page.goto("/submit");
  await waitOutBotGuard(page);

  await fillRequired(page);
  await page.getByLabel("Ссылка на документ").fill("javascript:alert(1)");
  await page.getByRole("button", { name: /Отправить/ }).click();

  await expect(page.getByText("Проверьте отмеченные поля.")).toBeVisible();
});

test("картинку вместо документа не принимает", async ({ page }) => {
  await page.goto("/submit");
  await waitOutBotGuard(page);

  await fillRequired(page);
  await page.getByLabel("Или файл").setInputFiles({
    name: "photo.png",
    mimeType: "image/png",
    buffer: Buffer.from("not a document"),
  });
  await page.getByRole("button", { name: /Отправить/ }).click();

  await expect(page.getByText(/можно приложить только/)).toBeVisible();
});

test("мгновенная отправка отбивается", async ({ page }) => {
  await page.goto("/submit");
  // Специально не ждём: имитируем бота, заполнившего форму за долю секунды.
  await fillRequired(page);
  await page.getByLabel("Ссылка на документ").fill("https://example.com/doc");
  await page.getByRole("button", { name: /Отправить/ }).click();

  await expect(page.getByText(/слишком быстро/i)).toBeVisible();
});
EOF
