import type { ReactNode } from "react";

/** Поле формы с подписью и местом под ошибку. */
export function Field({
  id,
  label,
  hint,
  error,
  children,
}: {
  id: string;
  label: string;
  hint?: string;
  error?: string;
  children: ReactNode;
}) {
  const hintId = hint ? `${id}-hint` : undefined;
  const errorId = error ? `${id}-error` : undefined;

  // Подсказка стоит после поля: так в две колонки поля встают на одну линию.
  // Связь с полем сохраняется через aria-describedby на самом поле.
  return (
    <div className="flex flex-col gap-2">
      <label htmlFor={id} className="text-ink" style={{ fontSize: "var(--text-sm)" }}>
        {label}
      </label>

      {children}

      {hint ? (
        <p
          id={hintId}
          className="text-ink-muted"
          style={{ fontSize: "var(--text-xs)" }}
        >
          {hint}
        </p>
      ) : null}

      {error ? (
        <p
          id={errorId}
          role="alert"
          className="text-danger"
          style={{ fontSize: "var(--text-xs)" }}
        >
          {error}
        </p>
      ) : null}
    </div>
  );
}

export const inputClass =
  "w-full border border-line bg-surface px-3 py-2.5 text-ink transition-colors " +
  "placeholder:text-ink-muted hover:border-ink-muted focus:border-accent " +
  "aria-[invalid=true]:border-danger";

