python3 - <<'PY'
import pathlib

# 1) флаг в env-схеме
p = pathlib.Path("src/lib/env.ts")
s = p.read_text()
s = s.replace('''/** Адрес сайта доступен и без остальных настроек — нужен для ссылок в разметке. */
export function siteUrl(): string {
  return process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000";
}''','''/** Адрес сайта доступен и без остальных настроек — нужен для ссылок в разметке. */
export function siteUrl(): string {
  return process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000";
}

/**
 * Пока флаг включён, сайт закрыт от поисковиков целиком.
 * Снимается одной настройкой, когда контент готов к публикации.
 */
export function isHiddenFromSearch(): boolean {
  return process.env.NEXT_PUBLIC_SITE_NOINDEX === "true";
}''')
p.write_text(s)

# 2) robots.ts
p = pathlib.Path("src/app/robots.ts")
p.write_text('''import type { MetadataRoute } from "next";

import { isHiddenFromSearch, siteUrl } from "@/lib/env";

export default function robots(): MetadataRoute.Robots {
  // Сайт ещё не готов к публикации — закрываем целиком.
  if (isHiddenFromSearch()) {
    return { rules: { userAgent: "*", disallow: "/" } };
  }

  return {
    rules: {
      userAgent: "*",
      allow: "/",
      // Присланные кейсы и служебные адреса поисковикам не нужны.
      disallow: ["/api/", "/cases/shared/", "/submit/thanks"],
    },
    sitemap: `${siteUrl()}/sitemap.xml`,
  };
}
''')

# 3) метатег в layout
p = pathlib.Path("src/app/layout.tsx")
s = p.read_text()
s = s.replace('import { siteUrl } from "@/lib/env";', 'import { isHiddenFromSearch, siteUrl } from "@/lib/env";')
s = s.replace('''  description: site.description,
  openGraph: {''','''  description: site.description,
  robots: isHiddenFromSearch() ? { index: false, follow: false } : undefined,
  openGraph: {''')
p.write_text(s)

# 4) sitemap пустеет, пока сайт скрыт
p = pathlib.Path("src/app/sitemap.ts")
s = p.read_text()
s = s.replace('import { siteUrl } from "@/lib/env";', 'import { isHiddenFromSearch, siteUrl } from "@/lib/env";')
s = s.replace('''  const base = siteUrl();
  const cases = await getPublicCases();''','''  if (isHiddenFromSearch()) return [];

  const base = siteUrl();
  const cases = await getPublicCases();''')
p.write_text(s)
print("флаг добавлен")
PY
for f in .env.example .env.local; do
  grep -q NEXT_PUBLIC_SITE_NOINDEX "$f" || printf '\n# Пока true — сайт закрыт от поисковиков целиком\nNEXT_PUBLIC_SITE_NOINDEX=true\n' >> "$f"
done
npx tsc --noEmit 2>&1 | head -5; pnpm lint 2>&1 | tail -3

