import { afterEach, describe, expect, it } from "vitest";

import { isHiddenFromSearch } from "@/lib/env";

const original = process.env.NEXT_PUBLIC_SITE_NOINDEX;

afterEach(() => {
  process.env.NEXT_PUBLIC_SITE_NOINDEX = original;
});

describe("выключатель видимости в поиске", () => {
  it("скрывает сайт только при точном значении true", () => {
    process.env.NEXT_PUBLIC_SITE_NOINDEX = "true";
    expect(isHiddenFromSearch()).toBe(true);
  });

  it("не срабатывает на другие значения", () => {
    for (const value of ["false", "1", "yes", ""]) {
      process.env.NEXT_PUBLIC_SITE_NOINDEX = value;
      expect(isHiddenFromSearch()).toBe(false);
    }
  });

  it("по умолчанию сайт открыт", () => {
    delete process.env.NEXT_PUBLIC_SITE_NOINDEX;
    expect(isHiddenFromSearch()).toBe(false);
  });
});
EOF
