input.command:
cat > tests/job-classifier.test.ts <<'EOF'
import { describe, expect, it } from "vitest";

import { classifyJob } from "@/lib/jobs/classify";

describe("уровень должности", () => {
  it("узнаёт C-level", () => {
    for (const title of [
      "CPO",
      "Chief Product Officer",
      "CMO / Директор по маркетингу",
      "Директор по продукту",
      "Директор по росту",
      "VP of Product",
      "Вице-президент по маркетингу",
      "Коммерческий директор по продукту",
    ]) {
      expect(classifyJob(title)?.level, title).toBe("c_level");
    }
  });

  it("узнаёт руководителей направления", () => {
    for (const title of [
      "Head of Product",
      "Head of Growth",
      "Руководитель отдела маркетинга",
      "Руководитель продуктового направления",
      "Лид продуктовой команды",
      "Team Lead продукта",
    ]) {
      expect(classifyJob(title)?.level, title).toBe("head");
    }
  });

  it("отбрасывает рядовые роли", () => {
    for (const title of [
      "Продакт-менеджер",
      "Senior Product Manager",
      "Product Owner",
      "Маркетолог",
      "Junior Growth Analyst",
      "Стажёр в продуктовую команду",
      "Аналитик",
      "Frontend-разработчик",
    ]) {
      expect(classifyJob(title), title).toBeNull();
    }
  });

  it("не путает похожие слова", () => {
    // «Руководитель отдела разработки» — не наша функция
    expect(classifyJob("Руководитель отдела разработки")).toBeNull();
    // «Head of Sales» — тоже мимо
    expect(classifyJob("Head of Sales")).toBeNull();
    // Ассистент директора по маркетингу — не руководящая роль
    expect(classifyJob("Ассистент директора по маркетингу")).toBeNull();
    expect(classifyJob("Помощник руководителя отдела маркетинга")).toBeNull();
  });
});

describe("функция", () => {
  it("различает продукт, маркетинг и рост", () => {
    expect(classifyJob("Head of Product")?.track).toBe("product");
    expect(classifyJob("Директор по маркетингу")?.track).toBe("marketing");
    expect(classifyJob("Head of Growth")?.track).toBe("growth");
    expect(classifyJob("CGO")?.track).toBe("growth");
    expect(classifyJob("CMO")?.track).toBe("marketing");
    expect(classifyJob("CPO")?.track).toBe("product");
  });

  it("при совпадении нескольких выбирает главное слово в начале", () => {
    expect(classifyJob("Head of Growth Marketing")?.track).toBe("growth");
    expect(classifyJob("Директор по продукту и маркетингу")?.track).toBe("product");
  });

  it("не срабатывает на чужие функции", () => {
    expect(classifyJob("Head of Engineering")).toBeNull();
    expect(classifyJob("Директор по персоналу")).toBeNull();
    expect(classifyJob("Финансовый директор")).toBeNull();
  });
});

describe("устойчивость", () => {
  it("не спотыкается о регистр, дефисы и лишние слова", () => {
    expect(classifyJob("HEAD OF PRODUCT (remote)")?.level).toBe("head");
    expect(classifyJob("  head   of   growth  ")?.level).toBe("head");
    expect(classifyJob("Head of Product-маркетинга")?.level).toBe("head");
  });

  it("не падает на пустой строке", () => {
    expect(classifyJob("")).toBeNull();
    expect(classifyJob("   ")).toBeNull();
  });
});
EOF
