  /\bchief\b/,
  /\bvp\b/,
  /\bv\.p\.\b/,
  /\bvice[- ]president\b/,
  /\bвице-президент\b/,
  /\bдиректор\b/,
  /\bdirector\b/,
];

const HEAD = [
  /\bhead\b/,
  /\bруководител/,
  /\bлид\b/,
  /\bteam ?lead\b/,
  /\btech ?lead\b/,
  /\bначальник\b/,
];

/**
 * Слова функции. Порядок внутри списка не важен, важен порядок появления
 * в названии: «Head of Growth Marketing» — это рост, а не маркетинг.
 */
const TRACKS: ReadonlyArray<[JobTrack, RegExp]> = [
  [
    "growth",
    /\b(growth|рост[ауе]?|роста|монетизаци\w*|retention|удержани\w*|crm)\b/,
  ],
  ["product", /\b(product|продукт\w*|продуктов\w*)\b/],
  [
    "marketing",
    /\b(marketing|маркетинг\w*|бренд\w*|brand|performance|коммуникаци\w*)\b/,
  ],
];

/** Находит функцию, которая упомянута в названии раньше остальных. */
function detectTrack(title: string): JobTrack | null {
  let best: { track: JobTrack; at: number } | null = null;

  for (const [track, pattern] of TRACKS) {
    const match = pattern.exec(title);
    if (!match) continue;
    if (!best || match.index < best.at) {
      best = { track, at: match.index };
    }
  }

  return best?.track ?? null;
}

function detectLevel(title: string): JobLevel | null {
  if (C_LEVEL.some((pattern) => pattern.test(title))) return "c_level";
  if (HEAD.some((pattern) => pattern.test(title))) return "head";
  return null;
}

/**
 * Возвращает уровень и функцию, либо null — если вакансия не для этого раздела.
 */
export function classifyJob(title: string): JobClass | null {
  const normalized = normalize(title);
  if (!normalized) return null;

  if (NOT_A_LEAD.some((pattern) => pattern.test(normalized))) return null;

  for (const [pattern, result] of ABBREVIATIONS) {
    if (pattern.test(normalized)) return result;
  }

  const level = detectLevel(normalized);
  if (!level) return null;

  const track = detectTrack(normalized);
  if (!track) return null;

  return { level, track };
}
