/**
 * Разбор названия вакансии: подходит ли она разделу и к чему относится.
 *
 * Работает только по названию — этого хватает, чтобы отсеять лишнее,
 * а спорные случаи всё равно проходят ручную модерацию.
 *
 * Важно: в JavaScript \b и \w понимают только латиницу, поэтому границы
 * слов задаются явно через список букв обоих алфавитов.
 */

export type JobLevel = "head" | "c_level";
export type JobTrack = "product" | "marketing" | "growth";

export type JobClass = { level: JobLevel; track: JobTrack };

const LETTER = "a-zа-я0-9";

/** Слово целиком: границы с обеих сторон. */
function whole(body: string): RegExp {
  return new RegExp(`(?<![${LETTER}])(?:${body})(?![${LETTER}])`);
}

/** Начало слова: окончание может быть любым (руководитель, руководителя…). */
function starts(body: string): RegExp {
  return new RegExp(`(?<![${LETTER}])(?:${body})`);
}

/** Приводим к разбираемому виду: нижний регистр, один пробел, ё → е. */
function normalize(title: string): string {
  return title
    .toLowerCase()
    .replaceAll("ё", "е")
    .replace(/[–—]/g, "-")
    .replace(/[^a-zа-я0-9()/+.-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** Роли, которые выглядят руководящими, но ими не являются. */
const NOT_A_LEAD = [
  starts("ассистент"),
  starts("помощник"),
  starts("стажер"),
  whole("intern"),
  starts("assistant"),
];

/** Аббревиатуры сразу задают и уровень, и функцию. */
const ABBREVIATIONS: ReadonlyArray<[RegExp, JobClass]> = [
  [whole("cpo"), { level: "c_level", track: "product" }],
  [whole("cmo"), { level: "c_level", track: "marketing" }],
  [whole("cgo"), { level: "c_level", track: "growth" }],
];

const C_LEVEL = [
  whole("chief"),
  whole("vp|v\\.p\\."),
  whole("vice[- ]president"),
  starts("вице-президент"),
  starts("директор"),
  starts("director"),
];

const HEAD = [
  whole("head"),
  starts("руководител"),
  whole("лид"),
  whole("team ?lead|tech ?lead"),
  starts("начальник"),
];

/**
 * Слова функций. Побеждает та, что упомянута в названии раньше:
 * «Head of Growth Marketing» — это рост, а не маркетинг.
 *
 * «рост» специально без свободного окончания, иначе в него попадает Ростов.
 */
const TRACKS: ReadonlyArray<[JobTrack, RegExp]> = [
  [
    "growth",
    new RegExp(
      `(?<![${LETTER}])(?:growth|рост[ауе]?(?![${LETTER}])|монетизац|retention|удержани|crm(?![${LETTER}]))`,
    ),
  ],
  ["product", starts("product|продукт")],
  ["marketing", starts("marketing|маркетинг|бренд|brand|performance|коммуникац")],
];

/** Находит функцию, упомянутую в названии раньше остальных. */
function detectTrack(title: string): JobTrack | null {
  let best: { track: JobTrack; at: number } | null = null;

  for (const [track, pattern] of TRACKS) {
    const match = pattern.exec(title);
    if (!match) continue;
    if (!best || match.index < best.at) best = { track, at: match.index };
  }

  return best?.track ?? null;
}

function detectLevel(title: string): JobLevel | null {
  if (C_LEVEL.some((pattern) => pattern.test(title))) return "c_level";
  if (HEAD.some((pattern) => pattern.test(title))) return "head";
  return null;
}

/** Уровень и функция, либо null — если вакансия не для этого раздела. */
export function classifyJob(title: string): JobClass | null {
  const normalized = normalize(title);
  if (!normalized) return null;

  if (NOT_A_LEAD.some((pattern) => pattern.test(normalized))) return null;

  for (const [pattern, result] of ABBREVIATIONS) {
    if (pattern.test(normalized)) return result;
  }

  const level = detectLevel(normalized);
  if (!level) return null;

  const track = detectTrack(normalized);
  if (!track) return null;

  return { level, track };
}
EOF
