cat > /tmp/claude-501/probe.mts <<'EOF'
import { classifyJob } from "/Users/urij/dev/cases/src/lib/jobs/classify";

const queries = ["продукт", "product", "маркетинг", "growth", "руководитель", "директор"];
const titles = new Set<string>();

for (const q of queries) {
  const xml = await fetch(
    "https://career.habr.com/vacancies/rss?q=" + encodeURIComponent(q) + "&type=all",
  ).then((r) => r.text());
  for (const m of xml.matchAll(/<title>([^<]*)<\/title>/g)) {
    const t = m[1].replace(/^Требуется «/, "").replace(/».*$/, "");
    if (t && !t.startsWith("Вакансии")) titles.add(t);
  }
}

const hits: string[] = [];
for (const t of titles) {
  const c = classifyJob(t);
  if (c) hits.push(`${c.level.padEnd(8)} ${c.track.padEnd(10)} ${t}`);
}

console.log("всего названий:", titles.size);
console.log("прошло фильтр:", hits.length);
console.log("---");
hits.forEach((h) => console.log(h));
EOF
