input.query:
-- Вакансии для руководителей в продукте, маркетинге и росте.
-- Собираются роботом, публикуются после ручного одобрения в Telegram.

create type public.job_status as enum ('pending', 'approved', 'rejected');
create type public.job_level  as enum ('head', 'c_level');
create type public.job_track  as enum ('product', 'marketing', 'growth');

create table public.jobs (
  id                  uuid primary key default gen_random_uuid(),
  created_at          timestamptz not null default now(),

  -- откуда взяли: 'habr', 'hh' и так далее
  source              text not null,
  source_id           text not null,

  title               text not null,
  company             text,
  location            text,
  url                 text not null,
  logo_url            text,
  -- зарплата строкой: источники отдают её в разных форматах
  salary              text,

  level               public.job_level not null,
  track               public.job_track not null,

  -- дата публикации у источника; по ней считается свежесть
  published_at        timestamptz not null,

  status              public.job_status not null default 'pending',
  reviewed_at         timestamptz,
  telegram_message_id bigint,

  -- один и тот же id у источника не заводим дважды
  constraint jobs_source_unique unique (source, source_id)
);

create index jobs_feed_idx on public.jobs (status, published_at desc);
create index jobs_pending_idx on public.jobs (created_at) where status = 'pending';

alter table public.jobs enable row level security;

comment on table public.jobs is 'Вакансии уровня Head и C-level. На сайте видны только approved и не старше двух недель.';
comment on column public.jobs.published_at is 'Дата публикации у источника. Вакансии старше 14 дней на сайте не показываются.';

