input.command:
cat > tests/habr-feed.test.ts <<'EOF'
import fs from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

import { parseHabrFeed } from "@/lib/jobs/habr";

const sample = fs.readFileSync(
  path.join(process.cwd(), "tests/fixtures/habr-sample.xml"),
  "utf8",
);

describe("разбор ленты Хабр Карьеры", () => {
  const items = parseHabrFeed(sample);

  it("находит все вакансии в ленте", () => {
    expect(items.length).toBe(50);
  });

  it("вытаскивает название без служебной обёртки", () => {
    const first = items[0]!;
    expect(first.title).toBe("Product Marketing Manager");
    expect(first.title).not.toContain("Требуется");
    expect(first.title).not.toContain("«");
  });

  it("вытаскивает компанию, ссылку и идентификатор", () => {
    const first = items[0]!;
    expect(first.company).toBe("Солар");
    expect(first.url).toBe("https://career.habr.com/vacancies/1000167222");
    expect(first.sourceId).toBe("1000167222");
  });

  it("разбирает дату публикации", () => {
    const first = items[0]!;
    expect(first.publishedAt).toMatch(/^2026-09-14T/);
    expect(Number.isNaN(Date.parse(first.publishedAt))).toBe(false);
  });

  it("определяет город и удалённую работу", () => {
    const withCity = items.find((item) => item.location === "Москва");
    expect(withCity).toBeDefined();

    const remote = items.find((item) => item.remote);
    expect(remote).toBeDefined();
  });

  it("у каждой вакансии есть обязательные поля", () => {
    for (const item of items) {
      expect(item.sourceId, item.title).toMatch(/^\d+$/);
      expect(item.title.length, item.title).toBeGreaterThan(0);
      expect(item.url, item.title).toMatch(/^https:\/\/career\.habr\.com\//);
    }
  });
});

describe("устойчивость разбора", () => {
  it("на пустой или мусорной строке возвращает пустой список", () => {
    expect(parseHabrFeed("")).toEqual([]);
    expect(parseHabrFeed("не xml вовсе")).toEqual([]);
    expect(parseHabrFeed("<rss><channel></channel></rss>")).toEqual([]);
  });

  it("пропускает вакансию без ссылки, а остальные разбирает", () => {
    const xml = `<rss><channel>
      <item><title>Требуется «Без ссылки»</title><guid>1</guid></item>
      <item><title>Требуется «С ссылкой»</title><guid>2</guid>
        <link>https://career.habr.com/vacancies/2</link>
        <pubDate>Mon, 14 Sep 2026 10:00:00 +0300</pubDate></item>
    </channel></rss>`;

    const items = parseHabrFeed(xml);
    expect(items).toHaveLength(1);
    expect(items[0]!.title).toBe("С ссылкой");
  });

  it("раскодирует спецсимволы в названии", () => {
    const xml = `<rss><channel><item>
      <title>Требуется «Head of Product &amp; Growth»</title>
      <guid>7</guid>
      <link>https://career.habr.com/vacancies/7</link>
      <pubDate>Mon, 14 Sep 2026 10:00:00 +0300</pubDate>
    </item></channel></rss>`;

    expect(parseHabrFeed(xml)[0]!.title).toBe("Head of Product & Growth");
  });
});
EOF
echo "тесты готовы"

