    .replace(/&(?:amp|lt|gt|quot|apos|nbsp|#39);/g, (entity) => ENTITIES[entity] ?? entity)
    .trim();
}

function tag(item: string, name: string): string | null {
  const match = new RegExp(`<${name}>([\\s\\S]*?)</${name}>`).exec(item);
  return match ? decode(match[1]!) : null;
}

/**
 * Заголовок приходит в виде: Требуется «Название» (Город).
 * Возвращаем отдельно название и город.
 */
function parseTitle(raw: string): { title: string; location: string | null } {
  const unwrapped = raw.replace(/^Требуется\s*/i, "").trim();

  const withCity = /^«(.+)»\s*\((.+)\)$/s.exec(unwrapped);
  if (withCity) {
    return { title: withCity[1]!.trim(), location: withCity[2]!.trim() };
  }

  const quoted = /^«(.+)»$/s.exec(unwrapped);
  if (quoted) return { title: quoted[1]!.trim(), location: null };

  return { title: unwrapped, location: null };
}

/** Разбирает ленту. Битые записи пропускает, остальные отдаёт. */
export function parseHabrFeed(xml: string): RawJob[] {
  const jobs: RawJob[] = [];

  for (const match of xml.matchAll(/<item>([\s\S]*?)<\/item>/g)) {
    const item = match[1]!;

    const rawTitle = tag(item, "title");
    const url = tag(item, "link");
    const pubDate = tag(item, "pubDate");
    const guid = tag(item, "guid");

    if (!rawTitle || !url) continue;

    const sourceId = guid ?? /\/vacancies\/(\d+)/.exec(url)?.[1] ?? null;
    if (!sourceId) continue;

    const published = pubDate ? new Date(pubDate) : null;
    if (!published || Number.isNaN(published.getTime())) continue;

    const { title, location } = parseTitle(rawTitle);
    if (!title) continue;

    const description = tag(item, "description") ?? "";

    jobs.push({
      sourceId,
      title,
      company: tag(item, "author"),
      location,
      remote: /удал[ёе]нн?о|remote/i.test(description),
      url,
      logoUrl: tag(item, "image"),
      publishedAt: published.toISOString(),
    });
  }

  return jobs;
}

/** Поисковые запросы, по которым обходим ленту. */
export const HABR_QUERIES = [
  "продукт",
  "product",
  "маркетинг",
  "marketing",
  "growth",
  "руководитель",
  "директор",
  "head of",
] as const;

export function habrFeedUrl(query: string): string {
  return `https://career.habr.com/vacancies/rss?q=${encodeURIComponent(query)}&type=all`;
}
