import fs from "node:fs/promises";
import path from "node:path";

import { parse as parseYaml } from "yaml";
import { z } from "zod";

import { classifyJob, type JobLevel, type JobTrack } from "./classify";

const FILE = path.join(process.cwd(), "content", "jobs.yml");

/** Вакансия старше этого срока со страницы пропадает. */
export const FRESH_DAYS = 14;

const entrySchema = z.object({
  title: z.string().min(3),
  company: z.string().min(1),
  url: z.url(),
  /** Дата публикации. По ней считается свежесть и порядок в списке. */
  posted: z.coerce.date(),
  location: z.string().min(1).optional(),
  remote: z.boolean().optional(),
  salary: z.string().min(1).optional(),
  /** Строка от себя: почему вакансия стоит внимания. */
  note: z.string().min(1).optional(),
  level: z.enum(["head", "c_level"]).optional(),
  track: z.enum(["product", "marketing", "growth"]).optional(),
});

export type Job = {
  id: string;
  title: string;
  company: string;
  url: string;
  posted: string;
  location: string | null;
  remote: boolean;
  salary: string | null;
  note: string | null;
  level: JobLevel;
  track: JobTrack;
};

/** Устойчивый ключ для React: ссылка у каждой вакансии своя. */
function makeId(url: string, title: string): string {
  return `${url}#${title}`;
}

/**
 * Читает и проверяет файл вакансий.
 * Ошибка в файле роняет сборку с понятным сообщением — так её видно сразу,
 * а не в виде пустого раздела на сайте.
 */
export async function loadAllJobs(): Promise<readonly Job[]> {
  let raw: string;
  try {
    raw = await fs.readFile(FILE, "utf8");
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }

  const parsed: unknown = parseYaml(raw);
  if (parsed === null || parsed === undefined) return [];

  if (!Array.isArray(parsed)) {
    throw new Error("content/jobs.yml должен быть списком вакансий");
  }

  return parsed.map((item, index) => {
    const result = entrySchema.safeParse(item);

    if (!result.success) {
      const problems = result.error.issues
        .map((issue) => `  ${issue.path.join(".") || "(запись)"}: ${issue.message}`)
        .join("\n");
      throw new Error(
        `Вакансия №${index + 1} в content/jobs.yml заполнена неверно:\n${problems}`,
      );
    }

    const entry = result.data;
    const guessed = classifyJob(entry.title);
    const level = entry.level ?? guessed?.level;
    const track = entry.track ?? guessed?.track;

    if (!level || !track) {
      throw new Error(
        `Вакансия «${entry.title}» (№${index + 1} в content/jobs.yml): ` +
          "не смог определить уровень и функцию по названию. " +
          "Допишите level (head или c_level) и track (product, marketing или growth).",
      );
    }

    return {
      id: makeId(entry.url, entry.title),
      title: entry.title,
      company: entry.company,
      url: entry.url,
      posted: entry.posted.toISOString(),
      location: entry.location ?? null,
      remote: entry.remote ?? false,
      salary: entry.salary ?? null,
      note: entry.note ?? null,
      level,
      track,
    };
  });
}

/** Вакансия ещё свежая? */
export function isFresh(posted: string, now: Date = new Date()): boolean {
  const age = now.getTime() - new Date(posted).getTime();
  return age >= 0 && age <= FRESH_DAYS * 24 * 60 * 60 * 1000;
}

/** Свежие вакансии, свежие сверху. */
export async function getFreshJobs(now: Date = new Date()): Promise<readonly Job[]> {
  const all = await loadAllJobs();
  return all
    .filter((job) => isFresh(job.posted, now))
    .sort((a, b) => b.posted.localeCompare(a.posted));
}
