import { describe, expect, it } from "vitest";

import { FRESH_DAYS, getFreshJobs, isFresh, loadAllJobs } from "@/lib/jobs/load";

const day = 24 * 60 * 60 * 1000;

describe("чтение файла вакансий", () => {
  it("читает вакансии с диска", async () => {
    const jobs = await loadAllJobs();
    expect(jobs.length).toBeGreaterThan(0);
  });

  it("определяет уровень и функцию по названию, когда их не указали", async () => {
    const jobs = await loadAllJobs();

    const head = jobs.find((job) => job.title === "Head of Product");
    expect(head).toMatchObject({ level: "head", track: "product" });

    const cgo = jobs.find((job) => job.title === "CGO");
    expect(cgo).toMatchObject({ level: "c_level", track: "growth" });
  });

  it("заполняет необязательные поля предсказуемо", async () => {
    const jobs = await loadAllJobs();
    for (const job of jobs) {
      expect(typeof job.remote).toBe("boolean");
      expect(job.location === null || typeof job.location === "string").toBe(true);
      expect(Number.isNaN(Date.parse(job.posted))).toBe(false);
    }
  });

  it("у каждой вакансии свой ключ", async () => {
    const jobs = await loadAllJobs();
    expect(new Set(jobs.map((job) => job.id)).size).toBe(jobs.length);
  });
});

describe("свежесть", () => {
  const now = new Date("2026-09-17T12:00:00Z");

  it("вчерашняя вакансия свежая", () => {
    expect(isFresh(new Date(now.getTime() - day).toISOString(), now)).toBe(true);
  });

  it("на границе в 14 дней ещё показывается", () => {
    const edge = new Date(now.getTime() - FRESH_DAYS * day + 1000).toISOString();
    expect(isFresh(edge, now)).toBe(true);
  });

  it("старше 14 дней — скрыта", () => {
    const old = new Date(now.getTime() - (FRESH_DAYS + 1) * day).toISOString();
    expect(isFresh(old, now)).toBe(false);
  });

  it("дата из будущего считается ошибкой и вакансия не показывается", () => {
    const future = new Date(now.getTime() + day).toISOString();
    expect(isFresh(future, now)).toBe(false);
  });
});

describe("список для страницы", () => {
  it("отдаёт свежие сверху", async () => {
    const jobs = await getFreshJobs(new Date("2026-09-17T12:00:00Z"));
    const dates = jobs.map((job) => job.posted);
    expect([...dates].sort().reverse()).toEqual(dates);
  });

  it("через месяц список пустеет сам", async () => {
    const jobs = await getFreshJobs(new Date("2026-11-01T12:00:00Z"));
    expect(jobs).toHaveLength(0);
  });
});
EOF
