import type { JobLevel, JobTrack } from "./classify";
import type { Job } from "./load";

export const TRACK_LABELS: Readonly<Record<JobTrack, string>> = {
  product: "Продукт",
  marketing: "Маркетинг",
  growth: "Рост",
};

export const LEVEL_LABELS: Readonly<Record<JobLevel, string>> = {
  head: "Head",
  c_level: "C-level",
};

export type JobFilter = { track: JobTrack | null; level: JobLevel | null };

const TRACKS = Object.keys(TRACK_LABELS) as JobTrack[];
const LEVELS = Object.keys(LEVEL_LABELS) as JobLevel[];

/** Читает фильтр из адреса страницы. Неизвестные значения игнорируются. */
export function parseFilter(params: {
  track?: string | string[];
  level?: string | string[];
}): JobFilter {
  const first = (value: string | string[] | undefined) =>
    Array.isArray(value) ? value[0] : value;

  const track = first(params.track);
  const level = first(params.level);

  return {
    track: TRACKS.includes(track as JobTrack) ? (track as JobTrack) : null,
    level: LEVELS.includes(level as JobLevel) ? (level as JobLevel) : null,
  };
}

export function applyFilter(
  jobs: readonly Job[],
  filter: JobFilter,
): readonly Job[] {
  return jobs.filter(
    (job) =>
      (filter.track === null || job.track === filter.track) &&
      (filter.level === null || job.level === filter.level),
  );
}

/**
 * Собирает адрес с изменённым фильтром.
 * Повторный клик по выбранному значению снимает его.
 */
export function filterHref(current: JobFilter, change: Partial<JobFilter>): string {
  const next = { ...current, ...change };
  const params = new URLSearchParams();

  if (next.track) params.set("track", next.track);
  if (next.level) params.set("level", next.level);

  const query = params.toString();
  return query ? `/jobs?${query}` : "/jobs";
}

/** Сколько вакансий в каждой функции — для подписей у кнопок. */
export function countBy<K extends string>(
  jobs: readonly Job[],
  key: (job: Job) => K,
): Readonly<Record<string, number>> {
  const counts: Record<string, number> = {};
  for (const job of jobs) {
    const value = key(job);
    counts[value] = (counts[value] ?? 0) + 1;
  }
  return counts;
}
EOF
cat > tests/jobs-filters.test.ts <<'EOF'
import { describe, expect, it } from "vitest";

import { applyFilter, countBy, filterHref, parseFilter } from "@/lib/jobs/filters";
import type { Job } from "@/lib/jobs/load";

const job = (over: Partial<Job>): Job => ({
  id: over.url ?? "x",
  title: "Head of Product",
  company: "Компания",
  url: "https://example.com/1",
  posted: "2026-09-15T00:00:00.000Z",
  location: null,
  remote: false,
  salary: null,
  note: null,
  level: "head",
  track: "product",
  ...over,
});

const jobs: Job[] = [
  job({ url: "1", track: "product", level: "head" }),
  job({ url: "2", track: "product", level: "c_level" }),
  job({ url: "3", track: "marketing", level: "c_level" }),
  job({ url: "4", track: "growth", level: "head" }),
];

describe("чтение фильтра из адреса", () => {
  it("понимает известные значения", () => {
    expect(parseFilter({ track: "growth", level: "c_level" })).toEqual({
      track: "growth",
      level: "c_level",
    });
  });

  it("игнорирует мусор в адресе", () => {
    expect(parseFilter({ track: "чтоугодно", level: "<script>" })).toEqual({
      track: null,
      level: null,
    });
  });

  it("берёт первое значение, если параметр повторили", () => {
    expect(parseFilter({ track: ["marketing", "product"] }).track).toBe("marketing");
  });

  it("без параметров фильтра нет", () => {
    expect(parseFilter({})).toEqual({ track: null, level: null });
  });
});

describe("отбор вакансий", () => {
  it("без фильтра отдаёт всё", () => {
    expect(applyFilter(jobs, { track: null, level: null })).toHaveLength(4);
  });

  it("фильтрует по функции", () => {
    expect(applyFilter(jobs, { track: "product", level: null })).toHaveLength(2);
  });

  it("фильтрует по уровню", () => {
    expect(applyFilter(jobs, { track: null, level: "c_level" })).toHaveLength(2);
  });

  it("совмещает оба условия", () => {
    const result = applyFilter(jobs, { track: "product", level: "c_level" });
    expect(result).toHaveLength(1);
    expect(result[0]!.url).toBe("2");
  });
});

describe("ссылки фильтра", () => {
  const empty = { track: null, level: null } as const;

  it("добавляет параметр", () => {
    expect(filterHref(empty, { track: "growth" })).toBe("/jobs?track=growth");
  });

  it("совмещает параметры", () => {
    expect(filterHref({ track: "product", level: null }, { level: "head" })).toBe(
      "/jobs?track=product&level=head",
    );
  });

  it("сбрасывает параметр обратно в чистый адрес", () => {
    expect(filterHref({ track: "product", level: null }, { track: null })).toBe("/jobs");
  });
});

describe("подсчёт", () => {
  it("считает вакансии по функциям", () => {
    expect(countBy(jobs, (job) => job.track)).toEqual({
      product: 2,
      marketing: 1,
      growth: 1,
    });
  });

  it("на пустом списке возвращает пусто", () => {
    expect(countBy([], (job) => job.track)).toEqual({});
  });
});
EOF
