      >
        {legend}
      </span>

      <ul className="flex flex-wrap gap-2">
        {options.map((option) => {
          const selected = option.value === active;
          return (
            <li key={option.label}>
              <Link
                href={hrefFor(option.value)}
                aria-current={selected ? "true" : undefined}
                className={
                  selected
                    ? "border border-accent bg-accent-soft px-3 py-1 text-accent"
                    : "border border-line px-3 py-1 text-ink-muted transition-colors hover:border-accent hover:text-accent"
                }
                style={{ borderRadius: "var(--radius-sm)", fontSize: "var(--text-xs)" }}
              >
                {option.label}
                {option.count !== undefined ? (
                  <span className="ml-1.5 opacity-60">{option.count}</span>
                ) : null}
              </Link>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/** Фильтры живут в адресе страницы, поэтому отбором можно поделиться ссылкой. */
