      <Row
        legend="Функция"
        active={filter.track}
        hrefFor={(value) =>
          filterHref(filter, { track: value as JobFilter["track"] })
        }
        options={[
          { value: null, label: "Все", count: total },
          ...Object.entries(TRACK_LABELS).map(([value, label]) => ({
            value,
            label,
            count: trackCounts[value] ?? 0,
          })),
        ]}
      />

      <Row
        legend="Уровень"
        active={filter.level}
        hrefFor={(value) =>
          filterHref(filter, { level: value as JobFilter["level"] })
        }
        options={[
          { value: null, label: "Любой" },
          ...Object.entries(LEVEL_LABELS).map(([value, label]) => ({
            value,
            label,
            count: levelCounts[value] ?? 0,
          })),
        ]}
      />
    </nav>
  );
}
