import Link from "next/link";

import {
  filterHref,
  LEVEL_LABELS,
  TRACK_LABELS,
  type JobFilter,
} from "@/lib/jobs/filters";

type Option = { value: string | null; label: string; count?: number };

function Row({
  legend,
  options,
  active,
  hrefFor,
}: {
  legend: string;
  options: Option[];
  active: string | null;
  hrefFor: (value: string | null) => string;
}) {
  return (
    <div className="flex flex-wrap items-baseline gap-x-4 gap-y-2">
      <span
        className="text-ink-muted"
        style={{ fontSize: "var(--text-xs)", minWidth: "6ch" }}
      >
        {legend}
      </span>

      <ul className="flex flex-wrap gap-2">
        {options.map((option) => {
          const selected = option.value === active;
          return (
            <li key={option.label}>
              <Link
                href={hrefFor(option.value)}
                aria-current={selected ? "true" : undefined}
                className={
                  selected
                    ? "border border-accent bg-accent-soft px-3 py-1 text-accent"
                    : "border border-line px-3 py-1 text-ink-muted transition-colors hover:border-accent hover:text-accent"
                }
                style={{ borderRadius: "var(--radius-sm)", fontSize: "var(--text-xs)" }}
              >
                {option.label}
                {option.count !== undefined ? (
                  <span className="ml-1.5 opacity-60">{option.count}</span>
                ) : null}
              </Link>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/** Фильтры живут в адресе страницы, поэтому отбором можно поделиться ссылкой. */
export function JobFilters({
  filter,
  trackCounts,
  levelCounts,
  total,
}: {
  filter: JobFilter;
  trackCounts: Readonly<Record<string, number>>;
  levelCounts: Readonly<Record<string, number>>;
  total: number;
}) {
  return (
    <nav aria-label="Фильтры вакансий" className="flex flex-col gap-4">
      <Row
        legend="Функция"
        active={filter.track}
        hrefFor={(value) =>
          filterHref(filter, { track: value as JobFilter["track"] })
        }
        options={[
          { value: null, label: "Все", count: total },
          ...Object.entries(TRACK_LABELS).map(([value, label]) => ({
            value,
            label,
            count: trackCounts[value] ?? 0,
          })),
        ]}
      />

      <Row
        legend="Уровень"
        active={filter.level}
        hrefFor={(value) =>
          filterHref(filter, { level: value as JobFilter["level"] })
        }
        options={[
          { value: null, label: "Любой" },
          ...Object.entries(LEVEL_LABELS).map(([value, label]) => ({
            value,
            label,
            count: levelCounts[value] ?? 0,
          })),
        ]}
      />
    </nav>
  );
}
