import type { Metadata } from "next";

import { JobCard } from "@/components/job/JobCard";
import { JobFilters } from "@/components/job/JobFilters";
import { Container } from "@/components/layout/Container";
import { applyFilter, countBy, parseFilter } from "@/lib/jobs/filters";
import { FRESH_DAYS, getFreshJobs } from "@/lib/jobs/load";

export const metadata: Metadata = {
  title: "Вакансии",
  description:
    "Отобранные вакансии уровня Head и C-level в продукте, маркетинге и росте.",
};

// Список меняется вместе с файлом вакансий, но зависит от текущей даты:
// раз в час пересчитываем, чтобы просроченные уходили сами.
export const revalidate = 3600;

export default async function JobsPage({ searchParams }: PageProps<"/jobs">) {
  const params = await searchParams;
  const filter = parseFilter(params);

  const jobs = await getFreshJobs();
  const visible = applyFilter(jobs, filter);

  const trackCounts = countBy(jobs, (job) => job.track);
  const levelCounts = countBy(jobs, (job) => job.level);

  return (
    <section
      aria-labelledby="jobs-heading"
      style={{ paddingBlock: "var(--space-section)" }}
    >
      <Container>
        <h1
          id="jobs-heading"
          className="font-display text-ink"
          style={{
            fontSize: "var(--text-2xl)",
            lineHeight: "var(--leading-tight)",
            maxWidth: "20ch",
          }}
        >
          Вакансии
        </h1>

        <p
          className="mt-6 text-ink-muted"
          style={{ fontSize: "var(--text-lg)", maxWidth: "var(--measure)" }}
        >
          Руководящие роли в продукте, маркетинге и росте — то, что я сам счёл
          стоящим внимания. Каждая вакансия висит {FRESH_DAYS} дней и пропадает,
          поэтому мёртвых ссылок здесь не копится.
        </p>

        {jobs.length > 0 ? (
          <div className="mt-12">
            <JobFilters
              filter={filter}
              trackCounts={trackCounts}
              levelCounts={levelCounts}
              total={jobs.length}
            />
          </div>
        ) : null}

        <div className="mt-10">
          {jobs.length === 0 ? (
            <p className="text-ink-muted">
              Сейчас пусто. Загляните через несколько дней — список обновляется
              дважды в неделю.
            </p>
          ) : visible.length === 0 ? (
            <p className="text-ink-muted">
              По этому отбору ничего нет. Снимите фильтр, чтобы увидеть остальные.
            </p>
          ) : (
            <div>
              {visible.map((job) => (
                <JobCard key={job.id} job={job} />
              ))}
            </div>
          )}
        </div>
      </Container>
    </section>
  );
}
