cat > e2e/jobs.spec.ts <<'EOF'
import { expect, test, type Page } from "@playwright/test";

/**
 * Вакансии — живой список: он меняется и со временем пустеет сам.
 * Поэтому тесты проверяют поведение страницы, а не конкретные вакансии.
 */

const cards = (page: Page) => page.locator("article");

test("страница вакансий открывается", async ({ page }) => {
  await page.goto("/jobs");

  await expect(page.getByRole("heading", { level: 1, name: "Вакансии" })).toBeVisible();
  await expect(page.getByText(/14 дней/)).toBeVisible();
});

test("вакансии есть в главном меню", async ({ page }) => {
  await page.goto("/");
  await page
    .getByRole("navigation", { name: "Основная навигация" })
    .getByRole("link", { name: "Вакансии" })
    .click();

  await expect(page).toHaveURL(/\/jobs$/);
});

test("фильтр по функции меняет адрес и список", async ({ page }) => {
  await page.goto("/jobs");

  const total = await cards(page).count();
  test.skip(total === 0, "список вакансий сейчас пуст");

  const filters = page.getByRole("navigation", { name: "Фильтры вакансий" });
  await filters.getByRole("link", { name: /^Продукт/ }).click();

  await expect(page).toHaveURL(/track=product/);

  const shown = await cards(page).count();
  expect(shown).toBeLessThanOrEqual(total);

  // Всё, что осталось на странице, относится к выбранной функции.
  for (const card of await cards(page).all()) {
    await expect(card).toContainText("Продукт");
  }
});

test("выбранный фильтр помечен и снимается повторным нажатием", async ({ page }) => {
  await page.goto("/jobs");
  test.skip((await cards(page).count()) === 0, "список вакансий сейчас пуст");

  const filters = page.getByRole("navigation", { name: "Фильтры вакансий" });
  const product = filters.getByRole("link", { name: /^Продукт/ });

  await product.click();
  await expect(
    filters.getByRole("link", { name: /^Продукт/ }),
  ).toHaveAttribute("aria-current", "true");

  await filters.getByRole("link", { name: /^Все/ }).click();
  await expect(page).toHaveURL(/\/jobs$/);
});

test("два фильтра совмещаются", async ({ page }) => {
  await page.goto("/jobs?track=product&level=c_level");

  const filters = page.getByRole("navigation", { name: "Фильтры вакансий" });
  test.skip((await filters.count()) === 0, "список вакансий сейчас пуст");

  await expect(filters.getByRole("link", { name: /^Продукт/ })).toHaveAttribute(
    "aria-current",
    "true",
  );
  await expect(filters.getByRole("link", { name: /^C-level/ })).toHaveAttribute(
    "aria-current",
    "true",
  );
});

test("мусор в адресе не ломает страницу", async ({ page }) => {
  const response = await page.goto("/jobs?track=%3Cscript%3E&level=что-угодно");

  expect(response?.status()).toBe(200);
  await expect(page.getByRole("heading", { level: 1, name: "Вакансии" })).toBeVisible();
  // Ничего не выбрано — фильтр сброшен к исходному виду.
  await expect(page.locator('[aria-current="true"]')).toHaveCount(0);
});

test("вакансии открываются на первоисточнике в новой вкладке", async ({ page }) => {
  await page.goto("/jobs");
  test.skip((await cards(page).count()) === 0, "список вакансий сейчас пуст");

  const link = cards(page).first().getByRole("link").first();
  await expect(link).toHaveAttribute("target", "_blank");
  await expect(link).toHaveAttribute("rel", /noopener/);
});
EOF
