import "server-only";

import { createHash } from "node:crypto";

import { serverEnv } from "./env";
import { supabaseAdmin } from "./supabase";

/** Сколько заявок с одного адреса разрешено за час. */
export const HOURLY_LIMIT = 3;

/** Подписка дешевле заявки, но и её стоит ограничить. */
export const SUBSCRIBE_HOURLY_LIMIT = 5;

const WINDOW_MS = 60 * 60 * 1000;

/** Сам IP не храним — только необратимый хеш с солью. */
export function hashIp(ip: string): string {
  return createHash("sha256").update(`${serverEnv().IP_HASH_SALT}:${ip}`).digest("hex");
}

/** Достаёт адрес клиента из заголовков прокси. */
export function clientIp(headers: Headers): string {
  const forwarded = headers.get("x-forwarded-for");
  if (forwarded) {
    const first = forwarded.split(",")[0]?.trim();
    if (first) return first;
  }
  return headers.get("x-real-ip")?.trim() || "unknown";
}

export type RateLimitResult = { allowed: boolean; used: number };

/**
 * Считает попытки за последний час и регистрирует текущую.
 * Если база недоступна — пропускаем запрос дальше: форма важнее лимита.
 */
export async function checkRateLimit(
  ipHash: string,
  limit: number = HOURLY_LIMIT,
): Promise<RateLimitResult> {

