import "server-only";

import { z } from "zod";

/**
 * Подписка на обновления через EmailOctopus.
 *
 * Список подписчиков живёт у них, а не у нас: мы не храним чужие адреса,
 * а подтверждение адреса и отписку сервис берёт на себя.
 */

const configSchema = z.object({
  apiKey: z.string().min(10),
  listId: z.string().min(5),
});

export type SubscribeConfig = z.infer<typeof configSchema>;

/** Настройки, если они заданы. Без них форма подписки на сайте не показывается. */
export function subscribeConfig(): SubscribeConfig | null {
  const parsed = configSchema.safeParse({
    apiKey: process.env.EMAILOCTOPUS_API_KEY,
    listId: process.env.EMAILOCTOPUS_LIST_ID,
  });

  return parsed.success ? parsed.data : null;
}

export function isSubscribeEnabled(): boolean {
  return subscribeConfig() !== null;
}

export type SubscribeOutcome = "pending" | "already" | "unavailable" | "error";

/** Похоже ли, что адрес уже в списке. */
function meansAlreadyThere(status: number, body: string): boolean {
  if (status === 409) return true;
  return /already|exists|duplicate/i.test(body);
}

/**
 * Добавляет адрес в список со статусом «ждёт подтверждения»:
 * EmailOctopus сам отправит письмо со ссылкой подтверждения.
 */
export async function addSubscriber(email: string): Promise<SubscribeOutcome> {
  const config = subscribeConfig();
  if (!config) return "unavailable";

  let response: Response;
  try {
    response = await fetch(
      `https://api.emailoctopus.com/lists/${config.listId}/contacts`,
      {
        method: "POST",
        headers: {
          authorization: `Bearer ${config.apiKey}`,
          "content-type": "application/json",
        },
        body: JSON.stringify({ email_address: email, status: "pending" }),
      },
    );
  } catch (error) {
    console.error("[subscribe] сервис рассылок недоступен:", error);
    return "error";
  }

  if (response.ok) return "pending";

  const body = await response.text().catch(() => "");

  if (meansAlreadyThere(response.status, body)) return "already";

  console.error(`[subscribe] ${response.status}: ${body.slice(0, 300)}`);
  return "error";
}
