import { NextResponse } from "next/server";

import {
  checkRateLimit,
  clientIp,
  hashIp,
  SUBSCRIBE_HOURLY_LIMIT,
} from "@/lib/rate-limit";
import { addSubscriber } from "@/lib/subscribe";
import { looksLikeBot, subscribeSchema } from "@/lib/validation";

export const runtime = "nodejs";

function text(form: FormData, key: string): string {
  const value = form.get(key);
  return typeof value === "string" ? value : "";
}

export async function POST(request: Request) {
  let form: FormData;
  try {
    form = await request.formData();
  } catch {
    return NextResponse.json(
      { ok: false, message: "Не удалось прочитать форму." },
      { status: 400 },
    );
  }

  // Ловушка для ботов: заполнили скрытое поле — делаем вид, что всё прошло.
  if (text(form, "website").trim().length > 0) {
    return NextResponse.json({ ok: true, state: "pending" });
  }

  const elapsedMs = Date.now() - Number(text(form, "startedAt") || 0);
  if (looksLikeBot("", elapsedMs)) {
    return NextResponse.json(
      { ok: false, message: "Слишком быстро. Попробуйте ещё раз." },
      { status: 400 },
    );
  }

  const parsed = subscribeSchema.safeParse({
    email: text(form, "email"),
    consent: text(form, "consent") === "on" || text(form, "consent") === "true",
  });

  if (!parsed.success) {
    const first = parsed.error.issues[0];
    return NextResponse.json(
      {
        ok: false,
        message: first?.message ?? "Проверьте поля.",
        field: String(first?.path[0] ?? ""),
      },
      { status: 400 },
    );
  }

  let ipHash: string;
  try {
    ipHash = hashIp(clientIp(request.headers), "subscribe");
  } catch (error) {
    console.error("[subscribe] окружение не настроено:", error);
    return NextResponse.json(
      { ok: false, message: "Подписка временно не работает." },
      { status: 503 },
    );
  }

  const limit = await checkRateLimit(ipHash, SUBSCRIBE_HOURLY_LIMIT);
  if (!limit.allowed) {
    return NextResponse.json(
      { ok: false, message: "Слишком много попыток. Попробуйте через час." },
      { status: 429 },
    );
  }

  const outcome = await addSubscriber(parsed.data.email);

  if (outcome === "pending") {
    return NextResponse.json({ ok: true, state: "pending" });
  }

  // Адрес уже в списке. Не говорим «вы подписаны» прямо: по ответу формы
  // не должно быть видно, есть чужой адрес в списке или нет.
  if (outcome === "already") {
    return NextResponse.json({ ok: true, state: "pending" });
  }

  if (outcome === "unavailable") {
    return NextResponse.json(
      { ok: false, message: "Подписка пока не настроена." },
      { status: 503 },
    );
  }

  return NextResponse.json(
    { ok: false, message: "Не получилось подписать. Попробуйте позже." },
    { status: 502 },
  );
}
