mkdir -p src/components/subscribe && cat > src/components/subscribe/SubscribeForm.tsx <<'EOF'
"use client";

import { useEffect, useRef, useState, type FormEvent } from "react";

type State = "idle" | "sending" | "done";

export function SubscribeForm() {
  const startedAt = useRef<number>(0);
  const [state, setState] = useState<State>("idle");
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    startedAt.current = Date.now();
  }, []);

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (state === "sending") return;

    setState("sending");
    setError(null);

    const form = new FormData(event.currentTarget);
    form.set("startedAt", String(startedAt.current));

    try {
      const response = await fetch("/api/subscribe", { method: "POST", body: form });
      const result = (await response.json()) as { ok: boolean; message?: string };

      if (!response.ok || !result.ok) {
        setError(result.message ?? "Не получилось. Попробуйте ещё раз.");
        setState("idle");
        return;
      }

      setState("done");
    } catch {
      setError("Нет связи с сервером. Попробуйте ещё раз.");
      setState("idle");
    }
  }

  if (state === "done") {
    return (
      <p role="status" className="text-ink" style={{ fontSize: "var(--text-base)" }}>
        Почти готово: на указанный адрес ушло письмо со ссылкой. Откройте его и
        подтвердите подписку — без этого писем не будет.
      </p>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate className="flex flex-col gap-4">
      {/* Ловушка для ботов: люди этого поля не видят. */}
      <div aria-hidden="true" className="absolute h-px w-px overflow-hidden opacity-0">
        <label htmlFor="subscribe-website">Не заполняйте это поле</label>
        <input
          id="subscribe-website"
          name="website"
          type="text"
          tabIndex={-1}
          autoComplete="off"
        />
      </div>

      <div className="flex flex-col gap-3 sm:flex-row">
        <label htmlFor="subscribe-email" className="sr-only">
          Ваша почта
        </label>
        <input
          id="subscribe-email"
          name="email"
          type="email"
          required
          autoComplete="email"
          placeholder="вы@почта.рф"
          aria-invalid={error ? true : undefined}
          aria-describedby={error ? "subscribe-error" : undefined}
          className="w-full border border-line bg-surface px-3 py-2.5 text-ink transition-colors placeholder:text-ink-muted hover:border-ink-muted focus:border-accent sm:max-w-xs"
        />

        <button
          type="submit"
          disabled={state === "sending"}
          className="border border-accent px-5 py-2.5 whitespace-nowrap text-accent transition-colors hover:bg-accent hover:text-paper disabled:cursor-not-allowed disabled:opacity-50"
          style={{ borderRadius: "var(--radius-sm)", fontSize: "var(--text-sm)" }}
        >
          {state === "sending" ? "Отправляю…" : "Подписаться"}
        </button>
      </div>

      <label
        className="flex items-start gap-3 text-ink-muted"
        style={{ fontSize: "var(--text-xs)", maxWidth: "52ch" }}
      >
        <input
          name="consent"
          type="checkbox"
          required
          className="mt-0.5 h-3.5 w-3.5 shrink-0 accent-[var(--accent)]"
        />
        <span>
          Согласен получать письма о новых кейсах и вакансиях. Отписаться можно
          из любого письма, адрес никому не передаётся.
        </span>
      </label>

      {error ? (
        <p
          id="subscribe-error"
          role="alert"
          className="text-danger"
          style={{ fontSize: "var(--text-xs)" }}
        >
          {error}
        </p>
      ) : null}
    </form>
  );
}
