import { Container } from "@/components/layout/Container";
import { isSubscribeEnabled } from "@/lib/subscribe";

import { SubscribeForm } from "./SubscribeForm";

/**
 * Блок подписки внизу страницы.
 * Пока сервис рассылок не настроен, блока на сайте просто нет —
 * форма, которая никуда не ведёт, хуже её отсутствия.
 */
export function SubscribeBand() {
  if (!isSubscribeEnabled()) return null;

  return (
    <section
      aria-labelledby="subscribe-heading"
      style={{ paddingBottom: "var(--space-section)" }}
    >
      <Container>
        <div
          className="border border-line bg-surface p-8"
          style={{ borderRadius: "var(--radius-md)" }}
        >
          <h2
            id="subscribe-heading"
            className="font-display text-ink"
            style={{ fontSize: "var(--text-xl)" }}
          >
            Письмо, когда появится что-то новое
          </h2>

          <p
            className="mt-2 mb-6 text-ink-muted"
            style={{ fontSize: "var(--text-sm)", maxWidth: "var(--measure)" }}
          >
            Новый разобранный кейс или подборка руководящих вакансий. Не чаще
            раза в неделю, без рекламы.
          </p>

          <SubscribeForm />
        </div>
      </Container>
    </section>
  );
}
