import { expect, test, type Page } from "@playwright/test";

/**
 * Проверяем только то, что происходит до обращения к сервису рассылок:
 * настоящая подписка потребовала бы запроса наружу из теста.
 */

const band = (page: Page) =>
  page.getByRole("region", { name: "Письмо, когда появится что-то новое" });

async function waitOutBotGuard(page: Page) {
  await page.waitForTimeout(3200);
}

test("форма подписки есть на главной и на вакансиях", async ({ page }) => {
  for (const path of ["/", "/jobs"]) {
    await page.goto(path);
    await expect(band(page).getByRole("button", { name: "Подписаться" })).toBeVisible();
  }
});

test("без согласия подписка не проходит", async ({ page }) => {
  await page.goto("/");
  await waitOutBotGuard(page);

  await band(page).getByRole("textbox").fill("petr@example.com");
  await band(page).getByRole("button", { name: "Подписаться" }).click();

  await expect(page.getByText(/согласие на получение писем/)).toBeVisible();
});

test("кривой адрес не проходит", async ({ page }) => {
  await page.goto("/");
  await waitOutBotGuard(page);

  await band(page).getByRole("textbox").fill("не почта");
  await band(page).getByRole("checkbox").check();
  await band(page).getByRole("button", { name: "Подписаться" }).click();

  await expect(page.getByText(/проверьте адрес почты/)).toBeVisible();
});

test("мгновенная отправка отбивается", async ({ page }) => {
  await page.goto("/");
  // Специально не ждём: так ведёт себя бот.
  await band(page).getByRole("textbox").fill("bot@example.com");
  await band(page).getByRole("checkbox").check();
  await band(page).getByRole("button", { name: "Подписаться" }).click();

  await expect(page.getByText(/слишком быстро/i)).toBeVisible();
});

test("у поля почты есть подпись для скринридера", async ({ page }) => {
  await page.goto("/");
  await expect(band(page).getByLabel("Ваша почта")).toBeVisible();
});
EOF
