  '| практики', String(n('best-practices')).padStart(3),
  '| SEO', String(n('seo')).padStart(3),
  '| LCP', m('largest-contentful-paint'),
  '| CLS', m('cumulative-layout-shift'));
" 2>/dev/null; done

