import { Golos_Text, Literata } from "next/font/google";

import { SiteFooter } from "@/components/layout/SiteFooter";
import { SiteHeader } from "@/components/layout/SiteHeader";
import { isHiddenFromSearch, siteUrl } from "@/lib/env";
import { site } from "@/lib/site";

import "./globals.css";

/*
 * Два семейства, оба переменные — по одному файлу на начертание.
 * Literata читают: заголовки, лиды, текст кейса. Она рисовалась
 * для чтения с экрана и у неё хорошая кириллица.
 */
const read = Literata({
  subsets: ["latin", "cyrillic"],
  style: ["normal", "italic"],
  axes: ["opsz"],
  variable: "--font-read",
  display: "swap",
});

/* Golos Text работает: меню, подписи, фильтры, кнопки, поля, таблицы. */
const ui = Golos_Text({
  subsets: ["latin", "cyrillic"],
  variable: "--font-ui",
  display: "swap",
});

export const metadata: Metadata = {

