.prose li + li {
  margin-top: 0.5em;
}

/* Цитата — врезка, а не карточка с полоской слева. */
.prose blockquote {
  font-size: var(--text-lg);
  font-style: italic;
  line-height: 1.45;
  color: var(--ink);
  margin-block: 2em;
